  // 17.3 Fetch Job Specific Competencies for a tenant
  app.get("/api/tenant/:tenantId/job-competencies", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).trim() : 'default';
    const userId = rawUserId.toLowerCase();
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      
      const aliasUsers = getKhumaloNkosiAliases(userId);
      const candidateDocIds: string[] = [];
      for (const aUser of aliasUsers) {
        candidateDocIds.push(
          `job_competencies_${tenantId}_${aUser}`,
          `job_competencies_tenant-229_${aUser}`,
          `job_competencies_nkangala_auto_${aUser}`,
          `job_competencies_global_${aUser}`
        );
      }
      if (rawUserId !== userId) {
        candidateDocIds.unshift(
          `job_competencies_${tenantId}_${rawUserId}`,
          `job_competencies_tenant-229_${rawUserId}`,
          `job_competencies_nkangala_auto_${rawUserId}`,
          `job_competencies_global_${rawUserId}`
        );
      }

      for (const dId of candidateDocIds) {
        const { data } = await supabase
          .from('messages')
          .select('content')
          .eq('id', dId)
          .maybeSingle();

        if (data && data.content) {
          try {
            const parsed = JSON.parse(data.content);
            if (parsed && (parsed.isCleared || Array.isArray(parsed.competencies))) {
              if (parsed.isCleared || parsed.competencies.length === 0) {
                return res.json({ ...parsed, competencies: [], isCleared: true });
              }
              return res.json(parsed);
            }
          } catch (parseErr) {}
        }
      }

      // Check templates and draft docs fallback using exact primary-key lookup
      if (userId.includes('@')) {
        const draftAndTplIds = Array.from(new Set(
          aliasUsers.flatMap(aUser => [
            `draft_doc_${tenantId}_${aUser}`,
            `draft_doc_tenant-229_${aUser}`,
            `draft_doc_nkangala_auto_${aUser}`,
            `pa_templates_${tenantId}_${aUser}`,
            `pa_templates_tenant-229_${aUser}`,
            `pa_templates_nkangala_auto_${aUser}`
          ])
        ));
        const { data: draftDocs } = await supabase
          .from('messages')
          .select('content')
          .in('id', draftAndTplIds);

        if (draftDocs) {
          for (const dRow of draftDocs) {
            try {
              const p = JSON.parse(dRow.content);
              const t = p.templates ? p.templates[0] : (p.html || p);
              if (t) {
                const list = t.pulledKhuboniJscRows || t.pulledCompetencyRows || t.pulledCfoCompetencyRows || t.pulledPedCompetencyRows || t.pulledCorpCompetencyRows;
                if (list && Array.isArray(list) && list.length > 0) {
                  return res.json({
                    competencies: list
                  });
                }
              }
            } catch (e) {}
          }
        }
      }

      if (userId.includes('shabangusm')) {
        const shabanguJscs = SHABANGUSM_OFFICIAL_JSCS.map((j) => ({
          id: j.id,
          competency: j.competency,
          weight: j.weight,
          proficiency: `Level ${j.level}`,
          description: j.definition
        }));
        return res.json({ competencies: shabanguJscs });
      }

      if (userId.includes('rakauj')) {
        return res.json({ competencies: RAKAUJ_FULL_COMPETENCY_ROWS });
      }

      // Fallback to global default ONLY if userId is default or global
      if ((userId === 'default' || userId === 'global') && supabase && !isCircuitBreakerOpen()) {
        try {
          const { data: globalData } = await supabase
            .from('messages')
            .select('content')
            .eq('id', 'job_competencies_global')
            .maybeSingle();
          if (globalData && globalData.content) {
            return res.json(JSON.parse(globalData.content));
          }
        } catch (e) {}
      }

      if (userId.includes('nkangaladm.gov.za') || userId.includes('@')) {
        return res.json({ competencies: getGuaranteedUserJscs(userId) });
      }

      return res.json({ competencies: [] });
    } catch (err: any) {
      console.error("Job competencies load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // 17.4 Save Job Specific Competencies for a tenant
  app.post("/api/tenant/:tenantId/job-competencies", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).trim() : 'default';
    const userId = rawUserId.toLowerCase();
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      
      const canonicalTenant = (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
        ? 'tenant-229'
        : tenantId;
      const targetTenants = Array.from(new Set([canonicalTenant, tenantId]));

      let bodyToSave = req.body;
      if (Array.isArray(req.body)) {
        const { items: offloaded } = await offloadInlinePoeBlobs(req.body, userId, supabase);
        bodyToSave = offloaded;
      } else if (req.body && Array.isArray(req.body.competencies)) {
        const { items: offloaded } = await offloadInlinePoeBlobs(req.body.competencies, userId, supabase);
        bodyToSave = { ...req.body, competencies: offloaded };
      }
      const payload = JSON.stringify(bodyToSave);

      const targetUsers = userId !== 'default' ? getKhumaloNkosiAliases(userId) : ['default'];
      for (const uKey of targetUsers) {
        for (const tKey of targetTenants) {
          const uDocId = `job_competencies_${tKey}_${uKey}`;
          const { error } = await supabase
            .from('messages')
            .upsert({ 
              id: uDocId,
              tenant_id: tKey,
              sender_id: 'job_competencies_editor',
              sender_email: 'job_competencies@system.local',
              sender_name: 'Job Competencies Editor',
              content: payload,
              message_type: 'job_competencies_list',
              created_at: new Date().toISOString()
            }, { onConflict: 'id' });
          if (error) throw error;
        }
      }
      res.json({ success: true });
    } catch (err: any) {
      console.error("job-competencies save exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

