  // 17.5 Performance Assessment Master Configuration
  app.get("/api/tenant/:tenantId/performance-assessment-config", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const userId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);

      // Default static 5-row Performance Assessment Framework table
      const defaultConfig = {
        title: "Performance Assessment Framework & Rating Scale",
        subtitle: "Regulation 5-Point Rating Scale & Performance Evaluation Standards",
        description: "The performance assessment of the Employee will be based on the following statutory 5-point rating scale criteria.",
        notesAbove: "4.1 The Employee agrees to participate in the performance assessment and development system of the Municipality.\n4.2 The Employee undertakes to actively focus on consistent achievement of core performance standards, strategic KPAs, and prescribed competency levels.\n4.3 The performance assessment will be moderated and calculated in accordance with the following 5-point rating scale:",
        headers: [
          "Level",
          "Terminology / Rating Band",
          "Qualitative Description / Performance Criteria",
          "Scorecard Range (%)",
          "Remedial / Bonus Implication"
        ],
        rows: [
          [
            "5",
            "Outstanding Performance",
            "Performance far exceeds the standard expected of an employee at this level. The operational and strategic deliverables have demonstrated exceptional quality, innovation, and leadership throughout the financial year.",
            "130% - 167%",
            "Eligible for Maximum Performance Bonus consideration as per municipal framework regulations and policy."
          ],
          [
            "4",
            "Performance Significantly Above Expectations",
            "Performance is significantly higher than the standard expected in the position with respect to quality, quantity, and timeliness of deliverables.",
            "100% - 129%",
            "Eligible for Merit Performance Bonus consideration in accordance with performance moderation rules."
          ],
          [
            "3",
            "Fully Effective",
            "Performance fully meets the standard expected in all areas of the position. The employee has achieved 100% of agreed quarterly objectives and key performance indicators satisfactorily.",
            "100%",
            "Standard compliant delivery; maintains normal salary progression and good performance standing."
          ],
          [
            "2",
            "Performance Not Fully Effective",
            "Performance is below the standard required for the job in key areas. Corrective action and structured personal development plan (PDP) intervention required.",
            "60% - 99%",
            "Mandatory PDP targeted training; remedial action timeline established; ineligible for performance bonus."
          ],
          [
            "1",
            "Unacceptable Performance",
            "Performance does not meet the standard expected for the job. The employee has failed to demonstrate the minimum required output despite prior counseling and guidance.",
            "< 60%",
            "Formal capability / incapacity proceedings initiated in terms of applicable municipal regulations."
          ]
        ],
        notesBelow: "4.4 The personal development plan (PDP) will address any developmental needs identified during the competency assessment process.\n4.5 Performance evaluation results are subject to institutional moderation by the Departmental Performance Management Committee (DPMC) and Internal Audit verification.",
        updatedAt: new Date().toISOString(),
        updatedBy: "System Default"
      };

      // Retrieve all saved performance assessment configurations from Supabase to find the newest master version
      let latestDoc: any = null;
      let latestTimestamp = 0;

      const { data: allConfigs, error: queryErr } = await supabase
        .from('messages')
        .select('id, content, created_at')
        .eq('message_type', 'performance_assessment_config');

      if (!queryErr && allConfigs && allConfigs.length > 0) {
        for (const item of allConfigs) {
          if (!item.content) continue;
          try {
            const parsed = JSON.parse(item.content);
            if (parsed && Array.isArray(parsed.headers) && Array.isArray(parsed.rows) && parsed.rows.length > 0) {
              const timeVal = parsed.updatedAt ? new Date(parsed.updatedAt).getTime() : (item.created_at ? new Date(item.created_at).getTime() : 0);
              if (timeVal >= latestTimestamp) {
                latestTimestamp = timeVal;
                latestDoc = parsed;
              }
            }
          } catch (e) {}
        }
      }

      // If specific keys are needed as fallback
      if (!latestDoc) {
        const candidateKeys = [
          `perf_assessment_config_${tenantId}_${userId}`,
          `perf_assessment_config_${tenantId}`,
          `perf_assessment_config_global_master`,
          `perf_assessment_config_tenant-229`,
          `perf_assessment_config_demo-tenant`,
          `perf_assessment_config_default`
        ];

        for (const k of candidateKeys) {
          const { data } = await supabase
            .from('messages')
            .select('content')
            .eq('id', k)
            .maybeSingle();
          if (data && data.content) {
            try {
              const p = JSON.parse(data.content);
              if (p && Array.isArray(p.headers) && Array.isArray(p.rows) && p.rows.length > 0) {
                latestDoc = p;
                break;
              }
            } catch (e) {}
          }
        }
      }

      if (latestDoc) {
        return res.json(latestDoc);
      }

      return res.json(defaultConfig);
    } catch (err: any) {
      console.error("performance-assessment-config load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/tenant/:tenantId/performance-assessment-config", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const userId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const configData = req.body;
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      
      const nowIso = new Date().toISOString();
      const payload = {
        ...configData,
        updatedAt: nowIso,
        updatedBy: userId || 'User'
      };

      // Broadcast and save to all master keys across the database so EVERY user & tenant sees it
      const keysToSave = [
        'perf_assessment_config_global_master',
        `perf_assessment_config_${tenantId}`,
        'perf_assessment_config_tenant-229',
        'perf_assessment_config_demo-tenant',
        'perf_assessment_config_nkangala_auto',
        'perf_assessment_config_default'
      ];

      if (userId && userId !== 'default') {
        keysToSave.push(`perf_assessment_config_${tenantId}_${userId}`);
        keysToSave.push(`perf_assessment_config_${userId}`);
      }

      const upsertPromises = keysToSave.map(docId => 
        supabase
          .from('messages')
          .upsert({
            id: docId,
            tenant_id: tenantId,
            sender_id: 'perf_assessment_editor',
            sender_email: userId || 'system@mzansiflow.local',
            sender_name: 'Performance Assessment Editor',
            content: JSON.stringify(payload),
            message_type: 'performance_assessment_config',
            created_at: nowIso
          })
      );

      await Promise.allSettled(upsertPromises);

      // Also synchronize all existing records with message_type 'performance_assessment_config'
      try {
        await supabase
          .from('messages')
          .update({
            content: JSON.stringify(payload),
            created_at: nowIso
          })
          .eq('message_type', 'performance_assessment_config');
      } catch (syncErr) {
        console.warn("Could not batch update other performance_assessment_config records:", syncErr);
      }

      res.json({ success: true, config: payload });
    } catch (err: any) {
      console.error("performance-assessment-config save exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // 17.6 Review Timetable Master Configuration
  app.get("/api/tenant/:tenantId/review-timetable-config", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const userId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);

      // Default static 6-row Review Timetable table
      const defaultConfig = {
        title: "Schedule for Performance Reviews & Timetable",
        subtitle: "Statutory Performance Review Intervals & Compliance Discussions",
        description: "The performance of the Employee in relation to their performance agreement shall be reviewed on the following dates with the understanding that reviews in the second and fourth quarter may be conducted in more detail.",
        notesAbove: "8.1 The performance of each employee in relation to his / her performance agreement shall be reviewed according to the established institutional schedule below.\n8.2 The Employer shall keep a record of the mid-year review and annual assessment meetings.",
        headers: [
          "Review Interval / Milestone",
          "Evaluation Period",
          "Target Submission Date",
          "Review Framework & Mechanism",
          "Responsible Parties / Reviewers",
          "Output & Compliance Documentation"
        ],
        rows: [
          [
            "First Quarter (Q1) Review",
            "July - September",
            "October (First Week)",
            "Formal Progress Review & Portfolio of Evidence (POE) Submission",
            "Supervisor & Incumbent",
            "Q1 Performance Progress Report & Variance Remedial Plan"
          ],
          [
            "Second Quarter (Q2) / Mid-Year",
            "October - December",
            "January (Third Week)",
            "Comprehensive Mid-Year Assessment & S72 Formal Evaluation",
            "Supervisor, Evaluation Panel & Municipal Manager",
            "Section 72 Mid-Year Performance & Budget Adjustment Report"
          ],
          [
            "Third Quarter (Q3) Review",
            "January - March",
            "April (First Week)",
            "Formal Quarterly Milestone & Evidence Review",
            "Supervisor & Incumbent",
            "Q3 Performance Progress Assessment & KPI Status Report"
          ],
          [
            "Fourth Quarter (Q4) / Annual Assessment",
            "April - June",
            "July (Fourth Week)",
            "Comprehensive Annual Self-Assessment & Audit Reconciliation",
            "Supervisor, MM & Executive Mayor",
            "Annual Performance Report & Final Evidence Dossier"
          ],
          [
            "DPMC & Internal Audit Moderation",
            "July - August",
            "August (Third Week)",
            "Institutional Moderation, Evidence Verification & Audit Review",
            "DPMC / Internal Audit Committee",
            "Moderated Performance Scorecard & Quality Assurance Certificate"
          ],
          [
            "Council Tabling & Bonus Determination",
            "August - September",
            "September / October (Council Sitting)",
            "Final Tabling to Municipal Council & Public Disclosure",
            "Municipal Council, Mayor & Accounting Officer",
            "Adopted Council Resolution & Audited Annual Performance File"
          ]
        ],
        notesBelow: "8.3 Performance feedback shall be based on the Employer's assessment of the Employee's performance.\n8.4 The Employer will be entitled to review and make reasonable changes to the provisions of Annexure \"A\" from time to time for operational reasons. The Employee will be fully consulted before any such change is made.",
        updatedAt: new Date().toISOString(),
        updatedBy: "System Default"
      };

      // Retrieve all saved review timetable configurations from Supabase to find the newest master version
      let latestDoc: any = null;
      let latestTimestamp = 0;

      const { data: allConfigs, error: queryErr } = await supabase
        .from('messages')
        .select('id, content, created_at')
        .eq('message_type', 'review_timetable_config');

      if (!queryErr && allConfigs && allConfigs.length > 0) {
        for (const item of allConfigs) {
          if (!item.content) continue;
          try {
            const parsed = JSON.parse(item.content);
            if (parsed && Array.isArray(parsed.headers) && Array.isArray(parsed.rows) && parsed.rows.length > 0) {
              const timeVal = parsed.updatedAt ? new Date(parsed.updatedAt).getTime() : (item.created_at ? new Date(item.created_at).getTime() : 0);
              if (timeVal >= latestTimestamp) {
                latestTimestamp = timeVal;
                latestDoc = parsed;
              }
            }
          } catch (e) {}
        }
      }

      if (!latestDoc) {
        const candidateKeys = [
          `review_timetable_config_${tenantId}_${userId}`,
          `review_timetable_config_${tenantId}`,
          `review_timetable_config_global_master`,
          `review_timetable_config_tenant-229`,
          `review_timetable_config_demo-tenant`,
          `review_timetable_config_default`
        ];

        for (const k of candidateKeys) {
          const { data } = await supabase
            .from('messages')
            .select('content')
            .eq('id', k)
            .maybeSingle();
          if (data && data.content) {
            try {
              const p = JSON.parse(data.content);
              if (p && Array.isArray(p.headers) && Array.isArray(p.rows) && p.rows.length > 0) {
                latestDoc = p;
                break;
              }
            } catch (e) {}
          }
        }
      }

      if (latestDoc) {
        return res.json(latestDoc);
      }

      return res.json(defaultConfig);
    } catch (err: any) {
      console.error("review-timetable-config load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/tenant/:tenantId/review-timetable-config", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const userId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const configData = req.body;
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      
      const nowIso = new Date().toISOString();
      const payload = {
        ...configData,
        updatedAt: nowIso,
        updatedBy: userId || 'User'
      };

      // Broadcast and save to all master keys across the database so EVERY user & tenant sees it
      const keysToSave = [
        'review_timetable_config_global_master',
        `review_timetable_config_${tenantId}`,
        'review_timetable_config_tenant-229',
        'review_timetable_config_demo-tenant',
        'review_timetable_config_nkangala_auto',
        'review_timetable_config_default'
      ];

      if (userId && userId !== 'default') {
        keysToSave.push(`review_timetable_config_${tenantId}_${userId}`);
        keysToSave.push(`review_timetable_config_${userId}`);
      }

      const upsertPromises = keysToSave.map(docId => 
        supabase
          .from('messages')
          .upsert({
            id: docId,
            tenant_id: tenantId,
            sender_id: 'review_timetable_editor',
            sender_email: userId || 'system@mzansiflow.local',
            sender_name: 'Review Timetable Editor',
            content: JSON.stringify(payload),
            message_type: 'review_timetable_config',
            created_at: nowIso
          })
      );

      await Promise.allSettled(upsertPromises);

      // Also synchronize all existing records with message_type 'review_timetable_config'
      try {
        await supabase
          .from('messages')
          .update({
            content: JSON.stringify(payload),
            created_at: nowIso
          })
          .eq('message_type', 'review_timetable_config');
      } catch (syncErr) {
        console.warn("Could not batch update other review_timetable_config records:", syncErr);
      }

      res.json({ success: true, config: payload });
    } catch (err: any) {
      console.error("review-timetable-config save exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Helper to verify whether a KPI has genuine submission evidence (PoE files, actuals, scores, or manager review)
  const hasGenuineSubmissionEvidence = (item: any): boolean => {
    if (!item) return false;
    const docsCount =
      (Array.isArray(item.q1PoeDocs) ? item.q1PoeDocs.length : 0) +
      (Array.isArray(item.q2PoeDocs) ? item.q2PoeDocs.length : 0) +
      (Array.isArray(item.q3PoeDocs) ? item.q3PoeDocs.length : 0) +
      (Array.isArray(item.q4PoeDocs) ? item.q4PoeDocs.length : 0) +
      (Array.isArray(item.annualPoeDocs) ? item.annualPoeDocs.length : 0) +
      (Array.isArray(item.midtermPoeDocs) ? item.midtermPoeDocs.length : 0);
    if (docsCount > 0 || item.poeFileBase64 || item.poeFileName) return true;

    const hasNonEmptyVal = (v: any) => {
      if (v === undefined || v === null) return false;
      const s = String(v).trim();
      return s !== '' && s.toUpperCase() !== 'N/A';
    };
    const hasScoreVal = (v: any) => {
      if (v === undefined || v === null) return false;
      const n = parseFloat(String(v));
      return !isNaN(n) && n > 0;
    };

    if (
      hasNonEmptyVal(item.q1Actual) ||
      hasNonEmptyVal(item.q2Actual) ||
      hasNonEmptyVal(item.q3Actual) ||
      hasNonEmptyVal(item.q4Actual) ||
      hasNonEmptyVal(item.midtermActual) ||
      hasNonEmptyVal(item.annualActual) ||
      hasNonEmptyVal(item.q1Comment) ||
      hasNonEmptyVal(item.q2Comment) ||
      hasNonEmptyVal(item.q3Comment) ||
      hasNonEmptyVal(item.q4Comment) ||
      hasNonEmptyVal(item.evaluationComment) ||
      hasScoreVal(item.myScore) ||
      hasScoreVal(item.q1Score) ||
      hasScoreVal(item.q2Score) ||
      hasScoreVal(item.q3Score) ||
      hasScoreVal(item.q4Score) ||
      hasScoreVal(item.midtermScore)
    ) {
      return true;
    }

    const st = item.reviewStatus || item.reviewApprovalStatus || '';
    if (
      st === 'Approved' ||
      st === 'Reviewed' ||
      st === 'Revision Required' ||
      st === 'Rejected' ||
      st === 'Dispatched to Audit' ||
      st === 'Dispatched to Internal Audit' ||
      hasScoreVal(item.managerScore)
    ) {
      return true;
    }

    return false;
  };

  // Performance Plan (PPLAN) Helper to propagate and lock unique POE descriptions per KPI across all 4 quarters
  const sanitizePplanItem = (item: any, userEmail?: string): any => {
    if (!item) return item;
    
    // Fallback default description if absolutely nothing is specified
    const defaultFallback = item.kpi 
      ? `Signed verification report and evidence portfolio for: ${item.kpi}`
      : `Signed verification report and approved oversight portfolio files`;

    // Ensure we keep existing distinct values, or fallback to the general 'poe' (but only if 'poe' is not an aggregated string)
    let parentPoe = (item.poe || '').toString().trim();
    const isAggregated = parentPoe.includes('Q1:') || parentPoe.includes('Q2:') || parentPoe.includes('Q3:') || parentPoe.includes('Q4:');
    
    // Safe quarter fallbacks
    const q1Val = (item.q1Poe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();
    const q2Val = (item.q2Poe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();
    const midtermVal = (item.midtermPoe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();
    const q3Val = (item.q3Poe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();
    const q4Val = (item.q4Poe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();
    const annualVal = (item.annualRequiredPoe || (isAggregated ? '' : parentPoe) || defaultFallback).toString().trim();

    // Clean up any double/triple "Q1: Q1: Q1:" or multi-quarter aggregated repeating segments to completely restore/heal original texts!
    const cleanQuarterlyValue = (val: string): string => {
      if (!val) return defaultFallback;
      const tokens = val.split(/(?:Q1:|Q2:|Q3:|Q4:|midterm:|annual:|\n|\r)/gi);
      const cleanPieces = tokens
        .map(t => t.trim())
        .filter(t => t.length > 0 && !t.match(/^(?:Q\d|midterm|annual)$/i));
      
      if (cleanPieces.length > 0) {
        return cleanPieces[0];
      }
      return defaultFallback;
    };

    const finalQ1 = cleanQuarterlyValue(q1Val);
    const finalQ2 = cleanQuarterlyValue(q2Val);
    const finalMidterm = cleanQuarterlyValue(midtermVal);
    const finalQ3 = cleanQuarterlyValue(q3Val);
    const finalQ4 = cleanQuarterlyValue(q4Val);
    const finalAnnual = cleanQuarterlyValue(annualVal);

    // Regenerate a clean non-recursive parent poe
    const cleanParentPoe = [
      `Q1: ${finalQ1}`,
      `Q2: ${finalQ2}`,
      `Q3: ${finalQ3}`,
      `Q4: ${finalQ4}`
    ].join('\n');

    // Marianne Joubert's Clean Audit KPI: Quarter 1 MUST be locked as N/A because it is only applicable in Quarter 3
    const kpiDesc = (item.kpi || item.description || item.desc || '').toString().toLowerCase();
    const kpiNoNorm = String(item.kpiNo || item['kpi no'] || '').toUpperCase().trim();
    const isCleanAudit = kpiDesc.includes('clean audit');
    const uClean = (userEmail || '').toLowerCase();
    const isJoubert = uClean.includes('joubertm') || uClean.includes('joubert');
    const isMadihlaba = uClean.includes('madihlaba') || uClean.includes('madhilaba');
    const isMasekoFm = uClean.includes('masekofm');
    const isMotauAm = uClean.includes('motauam');

    let kpiNoVal = item.kpiNo;
    let annualTargetVal = item.annualTarget;
    let q1TargetVal = item.q1Target;
    let q2TargetVal = item.q2Target;
    let q3TargetVal = item.q3Target;
    let q4TargetVal = item.q4Target;
    let q1LockedVal = item.q1Locked;
    let q2LockedVal = item.q2Locked;
    let q3LockedVal = item.q3Locked;
    let q4LockedVal = item.q4Locked;

    if (isCleanAudit && isJoubert) {
      q1TargetVal = 'N/A';
      q1LockedVal = true;
      if (!q3TargetVal || q3TargetVal === 'N/A') {
        q3TargetVal = '1 (Clean audit)';
      }
    }

    // Phaswana Madihlaba: Lock KPI M_21 ("Attain a clean audit opinion by 31 December 2026") for Q1, Q3, Q4 (applicable in Q2)
    if (isMadihlaba && (kpiNoNorm === 'M_21' || kpiNoNorm === 'M-21' || isCleanAudit)) {
      kpiNoVal = 'M_21';
      q1TargetVal = 'N/A';
      q1LockedVal = true;
      if (!q2TargetVal || q2TargetVal === 'N/A') {
        q2TargetVal = '1 (Clean audit)';
      }
      q2LockedVal = false;
      q3TargetVal = 'N/A';
      q3LockedVal = true;
      q4TargetVal = 'N/A';
      q4LockedVal = true;
    }

    // Fikile Maseko: Lock KPI M_49 ("Number of Tourism Expo convened by 30 April 2027") for Q1, Q2, Q3 (only applicable in Q4)
    if (isMasekoFm && (kpiNoNorm === 'M_49' || kpiNoNorm === 'M-49' || kpiDesc.includes('tourism expo'))) {
      kpiNoVal = 'M_49';
      q1TargetVal = 'N/A';
      q1LockedVal = true;
      q2TargetVal = 'N/A';
      q2LockedVal = true;
      q3TargetVal = 'N/A';
      q3LockedVal = true;
      if (!q4TargetVal || q4TargetVal === 'N/A') {
        q4TargetVal = '1';
      }
      q4LockedVal = false;
    }

    // Asnath Motau: KPI 3 annual target and Q1 target = "2"
    if (isMotauAm && (kpiNoNorm === '3' || kpiDesc.includes('performance agreements signed with subordinates'))) {
      annualTargetVal = '2';
      if (!q1TargetVal || String(q1TargetVal).toLowerCase().includes('subordinate')) {
        q1TargetVal = '2';
      }
    }

    const isNonRejectedReviewStatus =
      item.reviewStatus === 'Submitted for Approval' ||
      item.reviewStatus === 'Submitted for Review' ||
      item.reviewStatus === 'Submitted' ||
      item.reviewStatus === 'Draft / Resubmitting' ||
      item.reviewStatus === 'Draft' ||
      item.reviewStatus === 'In Progress';
    let syncedReviewStatus = isNonRejectedReviewStatus
      ? item.reviewStatus
      : (item.reviewStatus || (item.reviewApprovalStatus === 'Approved' ? 'Approved' : (item.reviewApprovalStatus === 'Rejected' ? 'Revision Required' : undefined)));
    const syncedReviewApprovalStatus = isNonRejectedReviewStatus
      ? ''
      : (item.reviewApprovalStatus || (item.reviewStatus === 'Approved' ? 'Approved' : (item.reviewStatus === 'Revision Required' || item.reviewStatus === 'Rejected' ? 'Rejected' : undefined)));

    // Prevent blank template KPIs (no PoE files, no actuals, no scores, no manager review) from ever being locked as Submitted for Approval
    if (
      (syncedReviewStatus === 'Submitted for Approval' || syncedReviewStatus === 'Submitted for Review' || syncedReviewStatus === 'Submitted') &&
      !hasGenuineSubmissionEvidence(item)
    ) {
      syncedReviewStatus = 'Draft';
    }

    // Ensure legacy single-file POE attachments (poeFileBase64) are surfaced in q1PoeDocs ONLY if q1PoeDocs was never initialized as an array
    const cleanDocList = (arr: any): any[] => {
      if (!Array.isArray(arr)) return [];
      return arr.filter(Boolean).map((d: any) => {
        if (d && d.dataUrl && d.fileData) {
          const { fileData: _dup, ...restDoc } = d;
          return restDoc;
        }
        return d;
      });
    };

    let q1Docs = cleanDocList(item.q1PoeDocs);
    const q2Docs = cleanDocList(item.q2PoeDocs);
    const q3Docs = cleanDocList(item.q3PoeDocs);
    const q4Docs = cleanDocList(item.q4PoeDocs);
    const annualDocs = cleanDocList(item.annualPoeDocs);
    const midtermDocs = cleanDocList(item.midtermPoeDocs);

    const totalDocsCount = q1Docs.length + q2Docs.length + q3Docs.length + q4Docs.length + annualDocs.length + midtermDocs.length;
    if (totalDocsCount === 0 && item.poeFileBase64 && !Array.isArray(item.q1PoeDocs)) {
      q1Docs = [{
        id: `legacy-poe-${item.id || item.kpiNo || '1'}`,
        name: item.poeFileName || 'Submitted_Portfolio_of_Evidence.pdf',
        dataUrl: item.poeFileBase64,
        mimeType: 'application/pdf',
        uploadedAt: item.updatedAt || item.createdAt || new Date().toISOString(),
        uploadedBy: userEmail || item.evaluationUsername || 'Employee'
      }];
    }

    const allCleanDocs = [...q1Docs, ...q2Docs, ...q3Docs, ...q4Docs, ...annualDocs, ...midtermDocs];
    const firstCleanDoc = allCleanDocs[0];
    const { poeFileBase64: _removedRedundantBase64, ...restItem } = item;

    const isResubmittedOrSubmitted =
      syncedReviewStatus === 'Submitted for Approval' ||
      syncedReviewStatus === 'Submitted for Review' ||
      syncedReviewStatus === 'Submitted' ||
      Boolean(item.resubmittedAt);

    const normalizeQuarterPoeStatus = (st: any) => {
      if (isResubmittedOrSubmitted && (st === 'Revision Required' || st === 'Rejected')) {
        return 'Pending Verification';
      }
      return st;
    };

    return {
      ...restItem,
      kpiNo: kpiNoVal,
      annualTarget: annualTargetVal,
      poeFileName: firstCleanDoc ? firstCleanDoc.name : '',
      ...(syncedReviewStatus ? { reviewStatus: syncedReviewStatus } : {}),
      reviewApprovalStatus: syncedReviewApprovalStatus || '',
      ...(restItem.q1PoeStatus !== undefined ? { q1PoeStatus: normalizeQuarterPoeStatus(restItem.q1PoeStatus) } : {}),
      ...(restItem.q2PoeStatus !== undefined ? { q2PoeStatus: normalizeQuarterPoeStatus(restItem.q2PoeStatus) } : {}),
      ...(restItem.q3PoeStatus !== undefined ? { q3PoeStatus: normalizeQuarterPoeStatus(restItem.q3PoeStatus) } : {}),
      ...(restItem.q4PoeStatus !== undefined ? { q4PoeStatus: normalizeQuarterPoeStatus(restItem.q4PoeStatus) } : {}),
      q1Target: q1TargetVal,
      q2Target: q2TargetVal,
      q3Target: q3TargetVal,
      q4Target: q4TargetVal,
      q1Locked: q1LockedVal,
      ...(q2LockedVal !== undefined ? { q2Locked: q2LockedVal } : {}),
      ...(q3LockedVal !== undefined ? { q3Locked: q3LockedVal } : {}),
      ...(q4LockedVal !== undefined ? { q4Locked: q4LockedVal } : {}),
      poe: cleanParentPoe,
      annualRequiredPoe: finalAnnual,
      q1Poe: finalQ1,
      q2Poe: finalQ2,
      midtermPoe: finalMidterm,
      q3Poe: finalQ3,
      q4Poe: finalQ4,
      q1PoeDocs: q1Docs,
      q2PoeDocs: q2Docs,
      q3PoeDocs: q3Docs,
      q4PoeDocs: q4Docs,
      annualPoeDocs: annualDocs,
      midtermPoeDocs: midtermDocs
    };
  };

  // Dedicated PoE Attachment Blob Vault Helper:
  // Offloads large inline Base64 data: URLs from KPI and JSC items into individual `poe_blob_*` rows in Supabase
  // and replaces `doc.dataUrl` with `/api/poe/blob/<blobId>` so pplan_*, kpis_*, and job_competencies_* payloads stay lean with zero data loss.
  function makeDeterministicPoeBlobId(doc: any, userId: string, kpiId: string, qField: string): string {
    const rawId = String(doc?.id || `${userId}_${kpiId}_${qField}_${doc?.name || 'doc'}_${doc?.size || 0}`)
      .replace(/[^a-zA-Z0-9_.-]/g, '_')
      .slice(0, 140);
    return rawId.startsWith('poe_blob_') ? rawId : `poe_blob_${rawId}`;
  }

  async function offloadInlinePoeBlobs(
    items: any[],
    userId: string,
    supabaseClient: any
  ): Promise<{ items: any[]; offloadedCount: number }> {
    if (!Array.isArray(items) || items.length === 0 || !supabaseClient) {
      return { items: Array.isArray(items) ? items : [], offloadedCount: 0 };
    }
    let offloadedCount = 0;
    const nowIso = new Date().toISOString();
    const docFields = ['q1PoeDocs', 'q2PoeDocs', 'q3PoeDocs', 'q4PoeDocs', 'annualPoeDocs', 'midtermPoeDocs', 'poeDocs'];
    const nextItems: any[] = [];

    for (const item of items) {
      if (!item || typeof item !== 'object') {
        nextItems.push(item);
        continue;
      }
      const nextItem: any = { ...item };
      const kpiKey = String(item.id || item.jscNo || item.kpiNo || 'item');

      for (const qField of docFields) {
        const docs = nextItem[qField];
        if (!Array.isArray(docs) || docs.length === 0) continue;
        const nextDocs: any[] = [];
        for (const doc of docs) {
          if (!doc || typeof doc !== 'object') {
            nextDocs.push(doc);
            continue;
          }
          const rawData = String(doc.dataUrl || doc.fileData || '');
          const isLargeInlineBase64 =
            rawData.startsWith('data:') &&
            !rawData.startsWith('data:image/svg+xml') &&
            rawData.length > 1024;

          if (isLargeInlineBase64) {
            const blobId = makeDeterministicPoeBlobId(doc, userId, kpiKey, qField);
            const blobUrl = `/api/poe/blob/${encodeURIComponent(blobId)}`;
            const blobPayload = JSON.stringify({
              id: blobId,
              docId: doc.id || blobId,
              name: doc.name || 'PoE_Evidence_Document',
              mimeType: doc.mimeType || 'application/octet-stream',
              size: doc.size || Math.round((rawData.length * 3) / 4),
              uploadedAt: doc.uploadedAt || nowIso,
              uploadedBy: doc.uploadedBy || userId,
              userId,
              dataUrl: rawData
            });
            try {
              const { error: blobErr } = await supabaseClient
                .from('messages')
                .upsert({
                  id: blobId,
                  tenant_id: 'tenant-229',
                  sender_id: 'poe_blob_vault',
                  sender_email: userId || 'poe@system.local',
                  sender_name: doc.uploadedBy || 'PoE Attachment Vault',
                  content: blobPayload,
                  message_type: 'poe_blob_v1',
                  created_at: nowIso
                }, { onConflict: 'id' });

              if (!blobErr) {
                offloadedCount++;
                const { fileData: _removedFileData, ...cleanDoc } = doc;
                nextDocs.push({
                  ...cleanDoc,
                  id: doc.id || blobId,
                  dataUrl: blobUrl,
                  url: blobUrl
                });
              } else {
                nextDocs.push(doc);
              }
            } catch (_) {
              nextDocs.push(doc);
            }
          } else {
            nextDocs.push(doc);
          }
        }
        nextItem[qField] = nextDocs;
      }

      // Check quarterly objects (q1, q2, q3, q4) for nested poeDocs
      for (const qKey of ['q1', 'q2', 'q3', 'q4']) {
        const qObj = nextItem[qKey] || (nextItem.quarters && nextItem.quarters[qKey]);
        if (qObj && Array.isArray(qObj.poeDocs) && qObj.poeDocs.length > 0) {
          const nextQDocs: any[] = [];
          for (const doc of qObj.poeDocs) {
            if (!doc || typeof doc !== 'object') {
              nextQDocs.push(doc);
              continue;
            }
            const rawData = String(doc.dataUrl || doc.fileData || '');
            const isLargeInlineBase64 =
              rawData.startsWith('data:') &&
              !rawData.startsWith('data:image/svg+xml') &&
              rawData.length > 1024;
            if (isLargeInlineBase64) {
              const blobId = makeDeterministicPoeBlobId(doc, userId, kpiKey, `${qKey}_poeDocs`);
              const blobUrl = `/api/poe/blob/${encodeURIComponent(blobId)}`;
              const blobPayload = JSON.stringify({
                id: blobId,
                docId: doc.id || blobId,
                name: doc.name || 'JSC_PoE_Evidence',
                mimeType: doc.mimeType || 'application/octet-stream',
                size: doc.size || Math.round((rawData.length * 3) / 4),
                uploadedAt: doc.uploadedAt || nowIso,
                uploadedBy: doc.uploadedBy || userId,
                userId,
                dataUrl: rawData
              });
              try {
                const { error: blobErr } = await supabaseClient
                  .from('messages')
                  .upsert({
                    id: blobId,
                    tenant_id: 'tenant-229',
                    sender_id: 'poe_blob_vault',
                    sender_email: userId || 'poe@system.local',
                    sender_name: doc.uploadedBy || 'PoE Attachment Vault',
                    content: blobPayload,
                    message_type: 'poe_blob_v1',
                    created_at: nowIso
                  }, { onConflict: 'id' });

                if (!blobErr) {
                  offloadedCount++;
                  const { fileData: _removedFileData, ...cleanDoc } = doc;
                  nextQDocs.push({
                    ...cleanDoc,
                    id: doc.id || blobId,
                    dataUrl: blobUrl,
                    url: blobUrl
                  });
                } else {
                  nextQDocs.push(doc);
                }
              } catch (_) {
                nextQDocs.push(doc);
              }
            } else {
              nextQDocs.push(doc);
            }
          }
          if (nextItem[qKey]) nextItem[qKey] = { ...nextItem[qKey], poeDocs: nextQDocs };
          if (nextItem.quarters && nextItem.quarters[qKey]) {
            nextItem.quarters = {
              ...nextItem.quarters,
              [qKey]: { ...nextItem.quarters[qKey], poeDocs: nextQDocs }
            };
          }
        }
      }

      if (typeof nextItem.poeFileBase64 === 'string' && nextItem.poeFileBase64.startsWith('data:') && nextItem.poeFileBase64.length > 1024) {
        const legacyBlobId = makeDeterministicPoeBlobId({ id: `legacy_${userId}_${kpiKey}`, name: nextItem.poeFileName || 'PoE.pdf' }, userId, kpiKey, 'legacy');
        const legacyBlobUrl = `/api/poe/blob/${encodeURIComponent(legacyBlobId)}`;
        try {
          const { error: legErr } = await supabaseClient
            .from('messages')
            .upsert({
              id: legacyBlobId,
              tenant_id: 'tenant-229',
              sender_id: 'poe_blob_vault',
              sender_email: userId || 'poe@system.local',
              sender_name: 'PoE Attachment Vault',
              content: JSON.stringify({
                id: legacyBlobId,
                name: nextItem.poeFileName || 'Submitted_Portfolio_of_Evidence.pdf',
                mimeType: 'application/pdf',
                uploadedAt: nowIso,
                uploadedBy: userId,
                userId,
                dataUrl: nextItem.poeFileBase64
              }),
              message_type: 'poe_blob_v1',
              created_at: nowIso
            }, { onConflict: 'id' });
          if (!legErr) {
            offloadedCount++;
            if (!Array.isArray(nextItem.q1PoeDocs) || nextItem.q1PoeDocs.length === 0) {
              nextItem.q1PoeDocs = [{
                id: legacyBlobId,
                name: nextItem.poeFileName || 'Submitted_Portfolio_of_Evidence.pdf',
                mimeType: 'application/pdf',
                dataUrl: legacyBlobUrl,
                url: legacyBlobUrl,
                uploadedAt: nowIso,
                uploadedBy: userId
              }];
            }
            delete nextItem.poeFileBase64;
          }
        } catch (_) {}
      }

      nextItems.push(nextItem);
    }

    return { items: nextItems, offloadedCount };
  };

  // Direct PoE Blob Upload & Streaming Endpoints
  app.post("/api/poe/blob", async (req, res) => {
    try {
      const supabase = getSupabase();
      const { id, name, mimeType, size, dataUrl, uploadedAt, uploadedBy, userId } = req.body || {};
      if (!dataUrl || typeof dataUrl !== 'string') {
        return res.status(400).json({ error: "Missing dataUrl" });
      }
      const normUser = String(userId || uploadedBy || 'system').toLowerCase().trim();
      const blobId = makeDeterministicPoeBlobId({ id, name, size }, normUser, 'upload', 'poe');
      const blobUrl = `/api/poe/blob/${encodeURIComponent(blobId)}`;
      const nowIso = new Date().toISOString();

      const { error } = await supabase
        .from('messages')
        .upsert({
          id: blobId,
          tenant_id: 'tenant-229',
          sender_id: 'poe_blob_vault',
          sender_email: normUser,
          sender_name: uploadedBy || 'PoE Attachment Vault',
          content: JSON.stringify({
            id: blobId,
            docId: id || blobId,
            name: name || 'PoE_Evidence_Document',
            mimeType: mimeType || 'application/octet-stream',
            size: size || Math.round((dataUrl.length * 3) / 4),
            uploadedAt: uploadedAt || nowIso,
            uploadedBy: uploadedBy || normUser,
            userId: normUser,
            dataUrl
          }),
          message_type: 'poe_blob_v1',
          created_at: nowIso
        }, { onConflict: 'id' });

      if (error) {
        return res.status(500).json({ error: error.message });
      }
      return res.json({ success: true, blobId, url: blobUrl });
    } catch (err: any) {
      return res.status(500).json({ error: err.message || "Failed to store PoE blob" });
    }
  });

  app.get("/api/poe/blob/:blobId", async (req, res) => {
    try {
      const rawBlobId = String(req.params.blobId || '').trim();
      if (!rawBlobId) return res.status(400).json({ error: "Missing blobId" });
      const supabase = getSupabase();
      const { data, error } = await supabase
        .from('messages')
        .select('content')
        .eq('id', rawBlobId)
        .maybeSingle();

      if (error || !data || !data.content) {
        return res.status(404).json({ error: "PoE attachment not found" });
      }

      const parsed = typeof data.content === 'string' ? JSON.parse(data.content) : data.content;
      if (req.query.format === 'json') {
        return res.json(parsed);
      }

      const rawDataUrl = String(parsed.dataUrl || '');
      let mimeType = parsed.mimeType || 'application/octet-stream';
      let base64Part = rawDataUrl;

      if (rawDataUrl.startsWith('data:')) {
        const commaIdx = rawDataUrl.indexOf(',');
        if (commaIdx !== -1) {
          const header = rawDataUrl.slice(5, commaIdx);
          const semiIdx = header.indexOf(';');
          if (semiIdx !== -1 && header.slice(0, semiIdx)) {
            mimeType = header.slice(0, semiIdx);
          }
          base64Part = rawDataUrl.slice(commaIdx + 1);
        }
      }

      const fileBuffer = Buffer.from(base64Part, 'base64');
      const safeName = String(parsed.name || 'PoE_Document').replace(/["\r\n]/g, '_');
      res.setHeader('Content-Type', mimeType);
      res.setHeader('Content-Length', String(fileBuffer.length));
      res.setHeader('Content-Disposition', `inline; filename="${encodeURIComponent(safeName)}"`);
      res.setHeader('Cache-Control', 'public, max-age=31536000, immutable');
      return res.end(fileBuffer);
    } catch (err: any) {
      return res.status(500).json({ error: err.message || "Failed to load PoE attachment" });
    }
  });

  // Lightweight version check endpoint for polling without transferring multi-megabyte plans
  app.get("/api/tenant/:tenantId/pplan-version", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const userId = normalizeNkangalaEmail(rawUserId) || rawUserId;
    try {
      const supabase = getSupabase();
      const canonicalDocId = (routeTenantId === 'nkangala_auto' || routeTenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
        ? `pplan_tenant-229_${userId}`
        : `pplan_${routeTenantId}_${userId}`;
      const { data } = await supabase
        .from('messages')
        .select('id, created_at')
        .eq('id', canonicalDocId)
        .maybeSingle();
      return res.json({ id: canonicalDocId, updatedAt: data?.created_at || null });
    } catch (err: any) {
      return res.json({ id: null, updatedAt: null });
    }
  });

  // Helper to merge POE documents, actuals, scores, and custom KPIs from secondary pplan_ or kpis_ rows into a primary plan's items
  const mergePlanItemsWithSecondary = (
    primaryItems: any[],
    secondaryItemLists: any[][],
    appendUnmatched: boolean = false,
    authoritativePoe: boolean = false
  ): any[] => {
    const rawPrimary = Array.isArray(primaryItems) ? primaryItems.map(it => ({ ...it })) : [];
    const result: any[] = [];
    const seenPrimaryIds = new Map<string, number>();
    for (const item of rawPrimary) {
      if (!item) continue;
      const itemId = String(item.id || '').toLowerCase().trim();
      if (itemId && seenPrimaryIds.has(itemId)) {
        const existingIdx = seenPrimaryIds.get(itemId)!;
        const existing = result[existingIdx];
        for (const [k, v] of Object.entries(item)) {
          if (v !== undefined && v !== null && v !== '' && (existing[k] === undefined || existing[k] === null || existing[k] === '')) {
            existing[k] = v;
          }
        }
      } else {
        if (itemId) seenPrimaryIds.set(itemId, result.length);
        result.push(item);
      }
    }
    if (!secondaryItemLists || secondaryItemLists.length === 0) return result;

    const mergeDocArrays = (a?: any[], b?: any[]) => {
      const listA = Array.isArray(a) ? a : [];
      if (authoritativePoe) return listA;
      const listB = Array.isArray(b) ? b : [];
      if (listB.length === 0) return listA;
      if (listA.length === 0) return listB;
      const seen = new Map<string, any>();
      for (const doc of [...listA, ...listB]) {
        if (!doc) continue;
        const key = String(doc.id || doc.name || Math.random()).toLowerCase().trim();
        const existing = seen.get(key);
        const existingIsBlobUrl = Boolean(existing?.dataUrl && String(existing.dataUrl).startsWith('/api/poe/blob/'));
        const incomingIsBlobUrl = Boolean(doc?.dataUrl && String(doc.dataUrl).startsWith('/api/poe/blob/'));
        if (!existing || (!existing.dataUrl && doc.dataUrl) || (!existingIsBlobUrl && incomingIsBlobUrl)) {
          seen.set(key, doc);
        }
      }
      return Array.from(seen.values());
    };

    const isActionedStatus = (st?: string) =>
      st === 'Approved' || st === 'Revision Required' || st === 'Rejected' || st === 'Reviewed' || st === 'Dispatched to Audit' || st === 'Dispatched to Internal Audit';
    const isSubmittedStatus = (st?: string) =>
      st === 'Submitted for Approval' || st === 'Submitted for Review' || st === 'Submitted';
    const isExplicitDraftStatus = (st?: string) =>
      st === 'Draft' || st === 'In Progress' || st === 'Draft / Resubmitting';

    for (const secList of secondaryItemLists) {
      if (!Array.isArray(secList)) continue;
      for (const secItem of secList) {
        if (!secItem) continue;
        const secId = String(secItem.id || '').toLowerCase().trim();
        const secNo = String(secItem.kpiNo || secItem['kpi no'] || '').toLowerCase().trim();
        const secDesc = String(secItem.kpi || secItem.description || '').toLowerCase().trim();

        const matchIdx = result.findIndex(baseItem => {
          const bId = String(baseItem.id || '').toLowerCase().trim();
          const bNo = String(baseItem.kpiNo || baseItem['kpi no'] || '').toLowerCase().trim();
          const bDesc = String(baseItem.kpi || baseItem.description || '').toLowerCase().trim();
          return (secId && bId && secId === bId) ||
                 (secNo && bNo && secNo === bNo) ||
                 (secDesc && bDesc && secDesc.length > 8 && secDesc === bDesc);
        });

        if (matchIdx >= 0) {
          const base = result[matchIdx];
          const baseSt = base.reviewStatus || base.reviewApprovalStatus;
          const secSt = secItem.reviewStatus || secItem.reviewApprovalStatus;

          const countDocs = (it: any) =>
            (Array.isArray(it?.q1PoeDocs) ? it.q1PoeDocs.length : 0) +
            (Array.isArray(it?.q2PoeDocs) ? it.q2PoeDocs.length : 0) +
            (Array.isArray(it?.q3PoeDocs) ? it.q3PoeDocs.length : 0) +
            (Array.isArray(it?.q4PoeDocs) ? it.q4PoeDocs.length : 0) +
            (Array.isArray(it?.annualPoeDocs) ? it.annualPoeDocs.length : 0) +
            (Array.isArray(it?.midtermPoeDocs) ? it.midtermPoeDocs.length : 0);

          const getNewestDocUploadTs = (it: any) => {
            const docs = [
              ...(Array.isArray(it?.q1PoeDocs) ? it.q1PoeDocs : []),
              ...(Array.isArray(it?.q2PoeDocs) ? it.q2PoeDocs : []),
              ...(Array.isArray(it?.q3PoeDocs) ? it.q3PoeDocs : []),
              ...(Array.isArray(it?.q4PoeDocs) ? it.q4PoeDocs : []),
              ...(Array.isArray(it?.annualPoeDocs) ? it.annualPoeDocs : []),
              ...(Array.isArray(it?.midtermPoeDocs) ? it.midtermPoeDocs : [])
            ];
            let maxTs = 0;
            for (const d of docs) {
              const t = d?.uploadedAt ? new Date(d.uploadedAt).getTime() : 0;
              if (!isNaN(t) && t > maxTs) maxTs = t;
            }
            return maxTs;
          };

          const baseDocsCount = countDocs(base);
          const secDocsCount = countDocs(secItem);
          const baseNewestDocTs = getNewestDocUploadTs(base);
          const secNewestDocTs = getNewestDocUploadTs(secItem);

          const isEmployeeResubmission =
            Boolean(base.resubmittedAt) ||
            Boolean(secItem.resubmittedAt && isSubmittedStatus(secSt) && secDocsCount > 0) ||
            (authoritativePoe && isSubmittedStatus(base.reviewStatus) && (secSt === 'Revision Required' || secSt === 'Rejected')) ||
            (authoritativePoe && baseDocsCount > 0 && (baseDocsCount > secDocsCount || baseNewestDocTs > secNewestDocTs) && (secSt === 'Revision Required' || secSt === 'Rejected' || baseSt === 'Revision Required' || baseSt === 'Rejected'));

          let resolvedReviewStatus = base.reviewStatus;
          let resolvedApprovalStatus = base.reviewApprovalStatus;
          if (isEmployeeResubmission) {
            resolvedReviewStatus = isSubmittedStatus(base.reviewStatus)
              ? base.reviewStatus
              : (isSubmittedStatus(secSt) ? secItem.reviewStatus : 'Submitted for Approval');
            resolvedApprovalStatus = '';
          } else if (!isActionedStatus(baseSt) && (!isExplicitDraftStatus(base.reviewStatus) || !authoritativePoe || baseDocsCount === 0)) {
            if (isActionedStatus(secSt) && (hasGenuineSubmissionEvidence(secItem) || secDocsCount > 0)) {
              resolvedReviewStatus = secItem.reviewStatus || (secItem.reviewApprovalStatus === 'Approved' ? 'Approved' : 'Revision Required');
              resolvedApprovalStatus = secItem.reviewApprovalStatus || (secItem.reviewStatus === 'Approved' ? 'Approved' : 'Rejected');
            } else if (!isSubmittedStatus(baseSt) && isSubmittedStatus(secSt) && (hasGenuineSubmissionEvidence(secItem) || secDocsCount > 0)) {
              resolvedReviewStatus = secItem.reviewStatus;
            }
          }

          const mergedQ1Docs = mergeDocArrays(base.q1PoeDocs, secItem.q1PoeDocs);
          const mergedQ2Docs = mergeDocArrays(base.q2PoeDocs, secItem.q2PoeDocs);
          const mergedQ3Docs = mergeDocArrays(base.q3PoeDocs, secItem.q3PoeDocs);
          const mergedQ4Docs = mergeDocArrays(base.q4PoeDocs, secItem.q4PoeDocs);
          const mergedAnnualDocs = mergeDocArrays(base.annualPoeDocs, secItem.annualPoeDocs);
          const mergedMidtermDocs = mergeDocArrays(base.midtermPoeDocs, secItem.midtermPoeDocs);
          const allMergedDocs = [...mergedQ1Docs, ...mergedQ2Docs, ...mergedQ3Docs, ...mergedQ4Docs, ...mergedAnnualDocs, ...mergedMidtermDocs];

          const resolveQuarterPoeStatus = (baseQSt?: string, secQSt?: string, qDocs?: any[]) => {
            if (isEmployeeResubmission) {
              if (baseQSt === 'Approved') return 'Approved';
              if (Array.isArray(qDocs) && qDocs.length > 0) return 'Pending Verification';
              if (baseQSt === 'Revision Required' || baseQSt === 'Rejected' || secQSt === 'Revision Required' || secQSt === 'Rejected') {
                return 'Pending Verification';
              }
              return baseQSt || 'Pending Verification';
            }
            return (baseQSt && baseQSt !== 'Pending Verification') ? baseQSt : (secQSt || baseQSt);
          };

          result[matchIdx] = {
            ...base,
            ...(resolvedReviewStatus ? { reviewStatus: resolvedReviewStatus } : {}),
            reviewApprovalStatus: resolvedApprovalStatus || '',
            ...(base.resubmittedAt || secItem.resubmittedAt ? { resubmittedAt: base.resubmittedAt || secItem.resubmittedAt } : {}),
            managerScore: base.managerScore || secItem.managerScore,
            q1ManagerScore: base.q1ManagerScore || secItem.q1ManagerScore,
            q2ManagerScore: base.q2ManagerScore || secItem.q2ManagerScore,
            q3ManagerScore: base.q3ManagerScore || secItem.q3ManagerScore,
            q4ManagerScore: base.q4ManagerScore || secItem.q4ManagerScore,
            review: base.review || secItem.review,
            reviewComment: base.reviewComment || secItem.reviewComment,
            myScore: (base.myScore && base.myScore !== 'N/A') ? base.myScore : (secItem.myScore || base.myScore),
            q1Score: base.q1Score || secItem.q1Score,
            q2Score: base.q2Score || secItem.q2Score,
            q3Score: base.q3Score || secItem.q3Score,
            q4Score: base.q4Score || secItem.q4Score,
            evaluation: base.evaluation || secItem.evaluation,
            evaluationComment: base.evaluationComment || secItem.evaluationComment,
            q1Actual: base.q1Actual || secItem.q1Actual,
            q2Actual: base.q2Actual || secItem.q2Actual,
            q3Actual: base.q3Actual || secItem.q3Actual,
            q4Actual: base.q4Actual || secItem.q4Actual,
            midtermActual: base.midtermActual || secItem.midtermActual,
            q1Comment: base.q1Comment || secItem.q1Comment,
            q2Comment: base.q2Comment || secItem.q2Comment,
            q3Comment: base.q3Comment || secItem.q3Comment,
            q4Comment: base.q4Comment || secItem.q4Comment,
            q1Poe: base.q1Poe || secItem.q1Poe,
            q2Poe: base.q2Poe || secItem.q2Poe,
            q3Poe: base.q3Poe || secItem.q3Poe,
            q4Poe: base.q4Poe || secItem.q4Poe,
            q1PoeStatus: resolveQuarterPoeStatus(base.q1PoeStatus, secItem.q1PoeStatus, mergedQ1Docs),
            q2PoeStatus: resolveQuarterPoeStatus(base.q2PoeStatus, secItem.q2PoeStatus, mergedQ2Docs),
            q3PoeStatus: resolveQuarterPoeStatus(base.q3PoeStatus, secItem.q3PoeStatus, mergedQ3Docs),
            q4PoeStatus: resolveQuarterPoeStatus(base.q4PoeStatus, secItem.q4PoeStatus, mergedQ4Docs),
            q1PoeFeedback: base.q1PoeFeedback || secItem.q1PoeFeedback,
            q2PoeFeedback: base.q2PoeFeedback || secItem.q2PoeFeedback,
            q3PoeFeedback: base.q3PoeFeedback || secItem.q3PoeFeedback,
            q4PoeFeedback: base.q4PoeFeedback || secItem.q4PoeFeedback,
            poeFileBase64: undefined,
            poeFileName: allMergedDocs[0] ? allMergedDocs[0].name : (authoritativePoe ? '' : (base.poeFileName || secItem.poeFileName || '')),
            q1PoeDocs: mergedQ1Docs,
            q2PoeDocs: mergedQ2Docs,
            q3PoeDocs: mergedQ3Docs,
            q4PoeDocs: mergedQ4Docs,
            annualPoeDocs: mergedAnnualDocs,
            midtermPoeDocs: mergedMidtermDocs
          };
        } else if (appendUnmatched && (secItem.kpi || secItem.description || secItem.kpiNo)) {
          result.push({ ...secItem });
        }
      }
    }
    return result;
  };

  // Performance Plan (PPLAN) Routes
  app.get("/api/tenant/:tenantId/pplan", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const userId = normalizeNkangalaEmail(rawUserId) || rawUserId;
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      const documentId = `pplan_${tenantId}_${userId}`;

      // 0. Check in-memory pplanCache first so newly saved/extracted plans are returned immediately without waiting on large DB payloads
      let data: any = null;
      let error: any = null;
      let hadQueryError = false;

      const aliasUsers = getKhumaloNkosiAliases(userId);
      const primaryCacheKeys = Array.from(new Set([
        documentId,
        ...aliasUsers.flatMap(aUser => [
          `pplan_tenant-229_${aUser}`,
          `pplan_nkangala_auto_${aUser}`,
          `pplan_global_${aUser}`
        ])
      ]));
      if (userId.includes('mahlanguml') || userId.includes('mahlangulm') || userId.includes('mandlaml')) {
        primaryCacheKeys.push(
          `pplan_tenant-229_mahlanguml@nkangaladm.gov.za`,
          `pplan_tenant-229_mahlangulm@nkangaladm.gov.za`,
          `pplan_nkangala_auto_mahlanguml@nkangaladm.gov.za`,
          `pplan_nkangala_auto_mahlangulm@nkangaladm.gov.za`,
          `pplan_global_mahlanguml@nkangaladm.gov.za`,
          `pplan_global_mahlangulm@nkangaladm.gov.za`
        );
      }

      let newestCached: { raw: string; timestamp: number } | null = null;
      for (const cKey of primaryCacheKeys) {
        const cached = pplanCache.get(cKey);
        if (cached && cached.raw && (Date.now() - cached.timestamp < 30000)) {
          if (!newestCached || cached.timestamp >= newestCached.timestamp) {
            newestCached = cached;
          }
        }
      }
      if (newestCached) {
        data = { content: newestCached.raw };
      }

      if (!data) {
        // Fast Canonical Lookup First: query ONLY the canonical row (`pplan_tenant-229_${userId}` or `documentId`) first
        // so users with large embedded POE documents never download 40MB-80MB redundant rows on a single request!
        const canonicalDocId = (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
          ? `pplan_tenant-229_${userId}`
          : documentId;

        let batchRowsData: any[] = [];
        if (isTeamPmsCoOwner(userId)) {
          // For Team PMS co-owners (nsibandenp & zulune), fetch and merge across both accounts and team_evaluation / team_pplan
          const teamPmsKeys = Array.from(new Set([
            ...aliasUsers.flatMap(aUser => [
              `pplan_tenant-229_${aUser}`,
              `team_evaluation_tenant-229_${aUser}`,
              `team_pplan_tenant-229_${aUser}`,
              `pplan_nkangala_auto_${aUser}`
            ]),
            'team_pplan_tenant-229_all',
            'team_evaluation_tenant-229_all'
          ]));
          const batchRes = await supabase
            .from('messages')
            .select('id, content, created_at')
            .in('id', teamPmsKeys);
          if (batchRes.error) {
            error = batchRes.error;
            hadQueryError = true;
          } else if (Array.isArray(batchRes.data)) {
            batchRowsData = batchRes.data;
          }
        } else {
          const canonicalRes = await supabase
            .from('messages')
            .select('id, content, created_at')
            .eq('id', canonicalDocId)
            .maybeSingle();

          if (canonicalRes.error) {
            error = canonicalRes.error;
            hadQueryError = true;
          } else if (canonicalRes.data && canonicalRes.data.content) {
            batchRowsData = [canonicalRes.data];
          } else {
            // Canonical row missing: fall back to querying secondary pplan and kpis keys (including nkosibs/khumalobs aliases)
            const kpiCandidateKeys = Array.from(new Set(
              aliasUsers.flatMap(aUser => [
                `kpis_${tenantId}_${aUser}`,
                `kpis_tenant-229_${aUser}`,
                `kpis_nkangala_auto_${aUser}`,
                `kpis_global_${aUser}`
              ])
            ));
            const secondaryKeys = [...primaryCacheKeys.filter(k => k !== canonicalDocId), ...kpiCandidateKeys];
            const batchRes = await supabase
              .from('messages')
              .select('id, content, created_at')
              .in('id', secondaryKeys);

            if (batchRes.error) {
              error = batchRes.error;
              hadQueryError = true;
            } else if (Array.isArray(batchRes.data)) {
              batchRowsData = batchRes.data;
            }
          }
        }

        if (!hadQueryError && batchRowsData.length > 0) {
          const pplanRows = batchRowsData.filter((r: any) => {
            const rid = String(r.id || '');
            return rid.startsWith('pplan_') || rid.startsWith('team_evaluation_') || rid.startsWith('team_pplan_');
          });
          const kpiRows = batchRowsData.filter((r: any) => String(r.id || '').startsWith('kpis_'));

          const isSyntheticKpiItem = (it: any): boolean => {
            if (!it) return true;
            const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase().trim();
            const goal = String(it.strategicGoal || it.priorityIssue || '').toLowerCase().trim();
            return (
              desc.startsWith('achieve target deliverable kpi-') ||
              desc.startsWith('achieve 100% statutory compliance and operational targets for') ||
              desc.startsWith('ensure 100% adherence to departmental budget control and mfma expenditure guidelines in') ||
              desc.includes('maintain 100% resolution of public service queries and operational requests within prescribed slas') ||
              desc.includes('complete all mandatory individual performance reviews and personal development plan (pdp) targets for 2026/2027') ||
              goal.includes('aspirant local municipal aligned performance objective') ||
              goal.includes('local statutory priority target')
            );
          };

          const scorePlanCandidate = (row: any) => {
            try {
              const p = typeof row.content === 'string' ? JSON.parse(row.content) : row.content;
              if (!p) return { valid: false, isCleared: false, isReplacePlan: false, isCanonical: false, ts: 0, reviewCount: 0, itemCount: 0, realItemCount: 0, parsed: null };
              const list = Array.isArray(p) ? p : (p.items || p.rows || p.kpis || []);
              const isCleared = Boolean(p.metadata && p.metadata._isCleared === true);
              const isReplacePlan = Boolean(p.metadata && (p.metadata._replacePlan === true || p.metadata._allowItemDeletion === true || p.metadata._isFredExtracted === true));
              const isCanonical = String(row.id || '') === `pplan_tenant-229_${userId}` || String(row.id || '') === documentId;
              const tsStr = (p.metadata && (p.metadata._pushedAt || p.metadata.updatedAt)) || row.created_at || '';
              const ts = tsStr ? (new Date(tsStr).getTime() || 0) : 0;
              let reviewCount = 0;
              let realItemCount = 0;
              if (!isCleared && Array.isArray(list)) {
                list.forEach((it: any) => {
                  if (!isSyntheticKpiItem(it)) {
                    realItemCount += 1;
                  }
                  const st = it.reviewStatus || it.reviewApprovalStatus || '';
                  if (st === 'Approved' || st === 'Revision Required' || st === 'Rejected' || st === 'Reviewed' || st === 'Dispatched to Audit') {
                    reviewCount += 2;
                  } else if (st === 'Submitted for Approval' || st === 'Submitted for Review' || st === 'Submitted') {
                    reviewCount += 1;
                  }
                  const docsLen = (it.q1PoeDocs?.length || 0) + (it.q2PoeDocs?.length || 0) + (it.q3PoeDocs?.length || 0) + (it.q4PoeDocs?.length || 0) + (it.annualPoeDocs?.length || 0) + (it.midtermPoeDocs?.length || 0);
                  if (docsLen > 0) reviewCount += 1;
                });
              }
              return {
                valid: isCleared || (Array.isArray(list) && list.length > 0),
                isCleared,
                isReplacePlan,
                isCanonical,
                ts,
                reviewCount,
                itemCount: isCleared ? 0 : (Array.isArray(list) ? list.length : 0),
                realItemCount,
                parsed: Array.isArray(p) ? { metadata: {}, items: p, rows: p } : p,
                raw: typeof row.content === 'string' ? row.content : JSON.stringify(row.content)
              };
            } catch (e) {
              return { valid: false, isCleared: false, isReplacePlan: false, isCanonical: false, ts: 0, reviewCount: 0, itemCount: 0, realItemCount: 0, parsed: null, raw: '' };
            }
          };

          const pplanCandidates = pplanRows.map(scorePlanCandidate).filter(c => c.valid);
          const kpiCandidates = kpiRows.map(scorePlanCandidate).filter(c => c.valid);
          const candidates = pplanCandidates.length > 0 ? pplanCandidates : kpiCandidates;

          if (candidates.length > 0) {
            // Prioritize explicitly cleared or real (non-synthetic) plans, sorting by newest timestamp first for canonical/replaced/cleared plans
            candidates.sort((a, b) => {
              const aHasRealOrCleared = (a.isCleared || a.realItemCount > 0) ? 1 : 0;
              const bHasRealOrCleared = (b.isCleared || b.realItemCount > 0) ? 1 : 0;
              if (bHasRealOrCleared !== aHasRealOrCleared) return bHasRealOrCleared - aHasRealOrCleared;

              // If either candidate was explicitly cleared or authoritatively replaced/saved, newest timestamp wins immediately
              if (a.isCleared || b.isCleared || a.isReplacePlan || b.isReplacePlan) {
                if (b.ts !== a.ts) return b.ts - a.ts;
                if (b.isCanonical !== a.isCanonical) return (b.isCanonical ? 1 : 0) - (a.isCanonical ? 1 : 0);
              }

              if (b.isCanonical !== a.isCanonical && b.ts >= a.ts) return (b.isCanonical ? 1 : 0) - (a.isCanonical ? 1 : 0);
              if (b.ts !== a.ts) return b.ts - a.ts;
              if (b.reviewCount !== a.reviewCount) return b.reviewCount - a.reviewCount;
              return b.realItemCount - a.realItemCount;
            });

            const best = candidates[0];
            if (best.isCleared && best.parsed) {
              best.parsed.items = [];
              best.parsed.rows = [];
            } else {
              const baseItems = best.parsed?.items || best.parsed?.rows || best.parsed?.kpis || [];
              const secondaryLists: any[][] = [];
              for (let i = 1; i < candidates.length; i++) {
                if (candidates[i].isCleared) continue;
                const cItems = (candidates[i].parsed?.items || candidates[i].parsed?.rows || candidates[i].parsed?.kpis || []).filter((it: any) => !isSyntheticKpiItem(it));
                if (Array.isArray(cItems) && cItems.length > 0) secondaryLists.push(cItems);
              }
              if (pplanCandidates.length > 0 && kpiCandidates.length > 0) {
                for (const kc of kpiCandidates) {
                  if (kc.isCleared) continue;
                  const kItems = (kc.parsed?.items || kc.parsed?.rows || kc.parsed?.kpis || []).filter((it: any) => !isSyntheticKpiItem(it));
                  if (Array.isArray(kItems) && kItems.length > 0) secondaryLists.push(kItems);
                }
              }

              if (secondaryLists.length > 0 && best.parsed && !(best.parsed.metadata && best.parsed.metadata._isCleared)) {
                // Only enrich matching KPIs (appendUnmatched = false when baseItems already has real KPIs) so stale secondary rows never inflate KPI counts
                const merged = mergePlanItemsWithSecondary(baseItems, secondaryLists, baseItems.length === 0);
                best.parsed.items = merged;
                best.parsed.rows = merged;
              }
            }

            const finalRaw = JSON.stringify(best.parsed);
            data = { content: finalRaw };
            for (const cKey of primaryCacheKeys) {
              pplanCache.set(cKey, { raw: finalRaw, timestamp: Date.now() });
            }
          }
        }
      }

      // Universal fallback: if current document is missing or has 0 items, check alternative tenant documents in priority order
      let parsed = (data && data.content) ? (() => { try { return JSON.parse(data.content); } catch (e) { return null; } })() : null;
      let rawList = parsed ? (parsed.items || parsed.rows || parsed.kpis || []) : [];
      const isExplicitlyCleared = parsed && parsed.metadata && parsed.metadata._isCleared === true;

      if (!isExplicitlyCleared && (!parsed || !Array.isArray(rawList) || rawList.length === 0)) {
        let bestFallbackParsed: any = null;

        // Only check kpis_ documents if NO pplan document exists and NO database query error/timeout occurred
        if (!bestFallbackParsed && !hadQueryError) {
          const kpiFallbackKeys = aliasUsers.flatMap(aUser => [
            `kpis_tenant-229_${aUser}`,
            `kpis_nkangala_auto_${aUser}`,
            `kpis_global_${aUser}`
          ]);
          for (const kKey of kpiFallbackKeys) {
            const fbRes = await supabase.from('messages').select('content').eq('id', kKey).maybeSingle();
            if (fbRes.data && fbRes.data.content) {
              try {
                const fbParsed = JSON.parse(fbRes.data.content);
                const fbList = Array.isArray(fbParsed) ? fbParsed : (fbParsed.items || fbParsed.rows || fbParsed.kpis || []);
                if (Array.isArray(fbList) && fbList.length > 0) {
                  bestFallbackParsed = { metadata: fbParsed.metadata || {}, items: fbList, rows: fbList };
                  break;
                }
              } catch (e) {}
            }
          }
        }

        // Fallback: Check ipms_gm_performance_plans table if still no items found and no DB timeout occurred
        if (!bestFallbackParsed && !hadQueryError && userId) {
          try {
            const { data: gmPlan } = await supabase
              .from('ipms_gm_performance_plans')
              .select('*')
              .eq('user_email', userId)
              .maybeSingle();

            if (gmPlan && Array.isArray(gmPlan.items_payload) && gmPlan.items_payload.length > 0) {
              bestFallbackParsed = {
                metadata: {
                  sourceFileName: gmPlan.source_file_name || 'GM_Performance_Agreement.pdf',
                  _isFredExtracted: true
                },
                items: gmPlan.items_payload,
                rows: gmPlan.items_payload,
                kpas: gmPlan.kpas_payload || []
              };
            }
          } catch (gmErr) {
            console.warn("[PPLAN GM Fallback] Error reading GM plan:", gmErr);
          }
        }

        if (bestFallbackParsed) {
          parsed = bestFallbackParsed;
          // Do NOT overwrite pplan_${tenantId}_${userId} in Supabase during a GET fallback!
        }
      }

      // If a database timeout/error occurred and we have no cached data, return 503 instead of generating dummy KPIs that could overwrite the user's plan
      if (!parsed && hadQueryError) {
        return res.status(503).json({ error: "Database temporarily busy, please retry." });
      }

      // If user is Shabangu and parsed has fewer than 31 items, ensure all 31 official KPIs are merged
      if (userId.includes('shabangusm')) {
        const shabanguPplan = SHABANGUSM_OFFICIAL_KPIS.map((k, idx) => ({
          id: `pplan-shabangu-${idx + 1}`,
          kpiNo: k["kpi no"],
          strategicGoal: k["functional kpa"],
          kpi: k["kpi description"],
          baseline: k["baseline"],
          annualTarget: k["annual target"],
          q1Target: k["1st qtr target"],
          q2Target: k["2nd qtr target"],
          q3Target: k["3rd qtr target"],
          q4Target: k["4th qtr target"],
          budget: k["budget"],
          weighting: k["%wt"],
          poe: k["poe"],
          annualRequiredPoe: k["poe"],
          q1Poe: k["poe"],
          q2Poe: k["poe"],
          midtermPoe: k["poe"],
          q3Poe: k["poe"],
          q4Poe: k["poe"]
        }));

        if (!parsed || !Array.isArray(parsed.items) || parsed.items.length < 31) {
          const existingMap = new Map();
          if (parsed && Array.isArray(parsed.items)) {
            parsed.items.forEach((it: any) => {
              if (it.kpiNo) existingMap.set(String(it.kpiNo).toLowerCase().trim(), it);
            });
          }
          const mergedItems = shabanguPplan.map((officialItem) => {
            const match = existingMap.get(String(officialItem.kpiNo).toLowerCase().trim());
            return match ? { ...officialItem, ...match } : officialItem;
          });
          parsed = {
            metadata: { ...SHABANGUSM_METADATA, ...(parsed?.metadata || {}) },
            items: mergedItems,
            rows: mergedItems
          };
        }
      }

      // Never generate fake/dummy KPIs if no items exist; initialize empty items with user's directory metadata
      if (!isExplicitlyCleared && (!parsed || !Array.isArray(parsed.items))) {
        const uProfile = (await getConsolidatedUsersList(tenantId)).find((u: any) => (u.email || '').toLowerCase().trim() === userId.toLowerCase().trim());
        const name = uProfile?.fullName || uProfile?.name || userId.split('@')[0];
        const dept = uProfile?.department || 'Municipal Administration';
        const job = uProfile?.jobFunction || 'Municipal Official';
        parsed = {
          metadata: {
            ...(parsed?.metadata || {}),
            name,
            position: job,
            department: dept,
            manager: uProfile?.manager || '',
            managerEmail: uProfile?.managerEmail || '',
            reportTo: uProfile?.reportTo || uProfile?.manager || '',
            financialYear: '2026/2027'
          },
          items: [],
          rows: []
        };
      }

      if (parsed) {
        pplanCache.set(documentId, { raw: JSON.stringify(parsed), timestamp: Date.now() });
        // Automatically sync live profile details from User Management directory into metadata
        try {
          const consolidated = await getConsolidatedUsersList(tenantId);
          const uProfile = consolidated.find((u: any) => (u.email || '').toLowerCase().trim() === userId.toLowerCase().trim());
          if (uProfile) {
            if (!parsed.metadata) parsed.metadata = {};
            if (uProfile.fullName && (!parsed.metadata.name || parsed.metadata.name.includes('Cllr') || parsed.metadata.name.includes('Placeholder'))) {
              parsed.metadata.name = uProfile.fullName;
            }
            if (uProfile.jobFunction && (!parsed.metadata.position || parsed.metadata.position.includes('Placeholder'))) {
              parsed.metadata.position = uProfile.jobFunction;
              parsed.metadata.jobTitle = uProfile.jobFunction;
            }
            if (uProfile.department && !parsed.metadata.department) {
              parsed.metadata.department = uProfile.department;
            }
            if (uProfile.directorate && !parsed.metadata.directorate) {
              parsed.metadata.directorate = uProfile.directorate;
            }
            if (uProfile.manager) {
              parsed.metadata.manager = uProfile.manager;
            }
            if (uProfile.reportTo || uProfile.manager) {
              parsed.metadata.reportTo = uProfile.reportTo || uProfile.manager;
            }
            if (uProfile.managerEmail) {
              parsed.metadata.managerEmail = uProfile.managerEmail;
            }
          }
        } catch (profErr) {}

        if (!parsed.metadata) parsed.metadata = {};
        if (userId === 'joubertm@nkangaladm.gov.za' || userId === 'tloujmt@nkangaladm.gov.za') {
          parsed.metadata.manager = 'Solly Links';
          parsed.metadata.managerEmail = 'linkss@nkangaladm.gov.za';
          parsed.metadata.reportTo = 'Solly Links';
        }

        const rawItems = Array.isArray(parsed) ? parsed : (parsed.items || parsed.rows || parsed.kpis || []);
        const isSyntheticCheck = (it: any): boolean => {
          if (!it) return true;
          const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase().trim();
          const goal = String(it.strategicGoal || it.priorityIssue || '').toLowerCase().trim();
          return (
            desc.startsWith('achieve target deliverable kpi-') ||
            desc.startsWith('achieve 100% statutory compliance and operational targets for') ||
            desc.startsWith('ensure 100% adherence to departmental budget control and mfma expenditure guidelines in') ||
            desc.includes('maintain 100% resolution of public service queries and operational requests within prescribed slas') ||
            desc.includes('complete all mandatory individual performance reviews and personal development plan (pdp) targets for 2026/2027') ||
            goal.includes('aspirant local municipal aligned performance objective') ||
            goal.includes('local statutory priority target')
          );
        };
        const nonSyntheticItems = rawItems.filter((it: any) => !isSyntheticCheck(it));
        const effectiveRawItems = nonSyntheticItems.length > 0 ? nonSyntheticItems : rawItems;
        let sanitizedItems = isExplicitlyCleared
          ? []
          : effectiveRawItems.map((it: any) => sanitizePplanItem(it, userId));

        // Sindiso Moepi (moepis@nkangaladm.gov.za): KPI 25 and 26 are removed from performance plan
        if (userId.toLowerCase().includes('moepis')) {
          sanitizedItems = sanitizedItems.filter((it: any) => {
            const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
            const id = String(it.id || '').toLowerCase();
            const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
            if (no === '25' || no === '26') return false;
            if (id.endsWith('-25') || id.endsWith('-26')) return false;
            if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
            return true;
          });

          if (rawItems.length > sanitizedItems.length) {
            try {
              const updatePayload = JSON.stringify({ ...parsed, items: sanitizedItems, rows: sanitizedItems });
              const syncTenants = ['tenant-229', 'nkangala_auto', 'global'];
              for (const tId of syncTenants) {
                const uDocId = `pplan_${tId}_${userId}`;
                pplanCache.set(uDocId, { raw: updatePayload, timestamp: Date.now() });
                supabase.from('messages').upsert({
                  id: uDocId,
                  tenant_id: tId,
                  sender_id: 'pplan_editor_tool',
                  sender_email: 'pplan@system.local',
                  sender_name: 'PPLAN Editor',
                  content: updatePayload,
                  message_type: 'pplan_list',
                  created_at: new Date().toISOString()
                }).then(() => {}).catch(() => {});
              }
            } catch(e) {}
          }
        }

        // Tiisetso S. Mathere (matherets@nkangaladm.gov.za): KPI 13, 14 and 15 are removed permanently from performance plan
        if (userId.toLowerCase().includes('matherets')) {
          sanitizedItems = sanitizedItems.filter((it: any) => {
            const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
            const id = String(it.id || '').toLowerCase();
            const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
            if (no === '13' || no === '14' || no === '15') return false;
            if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
            if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
            return true;
          });

          if (rawItems.length > sanitizedItems.length) {
            try {
              const updatePayload = JSON.stringify({ ...parsed, items: sanitizedItems, rows: sanitizedItems });
              const syncTenants = ['tenant-229', 'nkangala_auto', 'global'];
              for (const tId of syncTenants) {
                const uDocId = `pplan_${tId}_${userId}`;
                pplanCache.set(uDocId, { raw: updatePayload, timestamp: Date.now() });
                supabase.from('messages').upsert({
                  id: uDocId,
                  tenant_id: tId,
                  sender_id: 'pplan_editor_tool',
                  sender_email: 'pplan@system.local',
                  sender_name: 'PPLAN Editor',
                  content: updatePayload,
                  message_type: 'pplan_list',
                  created_at: new Date().toISOString()
                }).then(() => {}).catch(() => {});
              }
            } catch(e) {}
          }
        }

        // Nonosi Xaba (xabang@nkangaladm.gov.za): KPI 11 ("Maximum acceptable percentage of staff vacancy rate (Circular 88) per quarter") removed from performance plan
        if (userId.toLowerCase().includes('xabang')) {
          const beforeLen = sanitizedItems.length;
          sanitizedItems = sanitizedItems.filter((it: any) => {
            const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
            if (desc.includes('staff vacancy rate')) return false;
            return true;
          });

          if (beforeLen > sanitizedItems.length) {
            try {
              const updatePayload = JSON.stringify({ ...parsed, items: sanitizedItems, rows: sanitizedItems });
              const syncTenants = ['tenant-229', 'nkangala_auto', 'global'];
              for (const tId of syncTenants) {
                const uDocId = `pplan_${tId}_${userId}`;
                pplanCache.set(uDocId, { raw: updatePayload, timestamp: Date.now() });
                supabase.from('messages').upsert({
                  id: uDocId,
                  tenant_id: tId,
                  sender_id: 'pplan_editor_tool',
                  sender_email: 'pplan@system.local',
                  sender_name: 'PPLAN Editor',
                  content: updatePayload,
                  message_type: 'pplan_list',
                  created_at: new Date().toISOString()
                }).then(() => {}).catch(() => {});
              }
            } catch(e) {}
          }
        }

        // Pheladi M. Naka (nakapm@nkangaladm.gov.za): Remove Circular 88 HR vacancy and suspension KPIs (items 26-32) that do not belong to EHP
        if (userId.toLowerCase().includes('nakapm')) {
          const beforeLen = sanitizedItems.length;
          sanitizedItems = sanitizedItems.filter((it: any) => {
            const id = String(it.id || '').toLowerCase();
            const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
            if (id.startsWith('kpi-sync-178970925981')) return false;
            if (desc.includes('staff vacancy rate') || desc.includes('vacant posts filled') || desc.includes('workplace skills plan') || desc.includes('suspended officials') || desc.includes('active suspensions') || desc.includes('declared their financial interests')) return false;
            return true;
          });

          if (beforeLen > sanitizedItems.length) {
            try {
              const updatePayload = JSON.stringify({ ...parsed, items: sanitizedItems, rows: sanitizedItems });
              const syncTenants = ['tenant-229', 'nkangala_auto', 'global'];
              for (const tId of syncTenants) {
                const uDocId = `pplan_${tId}_${userId}`;
                pplanCache.set(uDocId, { raw: updatePayload, timestamp: Date.now() });
                supabase.from('messages').upsert({
                  id: uDocId,
                  tenant_id: tId,
                  sender_id: 'pplan_editor_tool',
                  sender_email: 'pplan@system.local',
                  sender_name: 'PPLAN Editor',
                  content: updatePayload,
                  message_type: 'pplan_list',
                  created_at: new Date().toISOString()
                }).then(() => {}).catch(() => {});
              }
            } catch(e) {}
          }
        }

        // Reconcile metadata.submittedKpiIds and metadata.reviewStatus with sanitizedItems so unsubmitted plans never report as Submitted for Approval
        if (parsed.metadata) {
          const genuinelySubmittedIds = new Set(
            sanitizedItems
              .filter((it: any) =>
                it.reviewStatus === 'Submitted for Approval' ||
                it.reviewStatus === 'Submitted for Review' ||
                it.reviewStatus === 'Submitted' ||
                it.reviewStatus === 'Approved' ||
                it.reviewStatus === 'Reviewed' ||
                it.reviewStatus === 'Revision Required' ||
                it.reviewStatus === 'Dispatched to Audit' ||
                it.reviewStatus === 'Dispatched to Internal Audit'
              )
              .map((it: any) => String(it.id || ''))
          );
          if (Array.isArray(parsed.metadata.submittedKpiIds)) {
            parsed.metadata.submittedKpiIds = parsed.metadata.submittedKpiIds.filter((id: any) =>
              genuinelySubmittedIds.has(String(id || ''))
            );
          }
          if (
            (parsed.metadata.reviewStatus === 'Submitted for Approval' ||
              parsed.metadata.reviewStatus === 'Submitted for Review' ||
              parsed.metadata.reviewStatus === 'Submitted') &&
            genuinelySubmittedIds.size === 0
          ) {
            parsed.metadata.reviewStatus = 'Draft';
          }
        }

        // If any loaded KPI item still contains large inline Base64 data: URLs, offload them to poe_blob_* rows and persist slimmed plan
        const hasInlineBase64Docs = sanitizedItems.some((it: any) => {
          if (typeof it?.poeFileBase64 === 'string' && it.poeFileBase64.startsWith('data:') && it.poeFileBase64.length > 1024) return true;
          for (const qf of ['q1PoeDocs', 'q2PoeDocs', 'q3PoeDocs', 'q4PoeDocs', 'annualPoeDocs', 'midtermPoeDocs']) {
            if (Array.isArray(it?.[qf]) && it[qf].some((d: any) => typeof d?.dataUrl === 'string' && d.dataUrl.startsWith('data:') && !d.dataUrl.startsWith('data:image/svg+xml') && d.dataUrl.length > 1024)) {
              return true;
            }
          }
          return false;
        });

        if (hasInlineBase64Docs && supabase && !req.query.kpiId && req.query.onlySubmitted !== 'true') {
          try {
            const { items: slimmedItems, offloadedCount } = await offloadInlinePoeBlobs(sanitizedItems, userId, supabase);
            if (offloadedCount > 0) {
              sanitizedItems = slimmedItems;
              const slimPayload = JSON.stringify({ metadata: parsed.metadata || {}, items: slimmedItems });
              const canonicalTenant = (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
                ? 'tenant-229'
                : tenantId;
              for (const cKey of primaryCacheKeys) {
                pplanCache.set(cKey, { raw: slimPayload, timestamp: Date.now() });
              }
              setImmediate(() => {
                supabase.from('messages').upsert({
                  id: `pplan_${canonicalTenant}_${userId}`,
                  tenant_id: canonicalTenant,
                  sender_id: 'pplan_editor_tool',
                  sender_email: 'pplan@system.local',
                  sender_name: 'PPLAN Editor',
                  content: slimPayload,
                  message_type: 'pplan_list',
                  created_at: new Date().toISOString()
                }, { onConflict: 'id' }).then(() => {}).catch(() => {});
              });
            }
          } catch (_) {}
        }

        // Filter items dynamically to prevent transferring unnecessary historical data structure
        if (req.query.kpiId) {
          const targetKpiId = String(req.query.kpiId).trim().toLowerCase();
          sanitizedItems = sanitizedItems.filter((it: any) => 
            String(it.id).toLowerCase() === targetKpiId || 
            String(it.kpiNo).toLowerCase() === targetKpiId
          );
        } else if (req.query.onlySubmitted === 'true') {
          sanitizedItems = sanitizedItems.filter((it: any) => 
            it.reviewStatus === 'Submitted for Approval' || 
            it.reviewStatus === 'Submitted for Review' || 
            it.reviewStatus === 'Submitted'
          );
        }

        parsed.items = sanitizedItems;
        delete parsed.rows;
        return res.json(parsed);
      }
      return res.json({ metadata: {}, items: [] });
    } catch (err: any) {
      console.error("pplan load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Dedicated lightweight endpoint to check reports unlock status without transferring heavy payloads
  app.get("/api/tenant/:tenantId/reports-unlock-status", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const { userId, isManager } = req.query;
    try {
      const supabase = getSupabase();
      if (!supabase) return res.json({ unlocked: false });

      let tenantId = routeTenantId || 'nkangala_auto';
      let tenantIds = [tenantId];
      if (tenantId === 'nkangala_auto' || tenantId === 'tenant-229') {
        tenantIds = ['nkangala_auto', 'tenant-229'];
      }

      const normUser = (typeof userId === 'string' ? userId : '').toLowerCase().trim();
      const cacheKey = `reports_unlock_${tenantIds[0]}_${String(isManager) === 'true' ? 'mgr' : normUser}`;

      const result = await fetchWithCoalescing(cacheKey, 60000, async () => {
        if (String(isManager) === 'true') {
          // 1. Check in-memory pplanCache first to avoid database queries if already cached
          for (const [, cached] of pplanCache.entries()) {
            try {
              const raw = JSON.parse(cached.raw);
              const auditStatus = raw?.metadata?.internalAuditStatus;
              if (auditStatus === 'Audited' || auditStatus === 'Pushed to DPMC' || auditStatus === 'Pushed to Moderation') {
                return { unlocked: true };
              }
            } catch {}
          }

          // 2. Check lightweight audit_ledger and dpmc_ledger rows (~5KB) instead of scanning 100 full pplan_list rows
          const ledgerIds = [
            'audit_ledger_tenant-229',
            'audit_ledger_nkangala_auto',
            'dpmc_ledger_tenant-229',
            'dpmc_ledger_nkangala_auto'
          ];
          const { data: ledgerRows } = await supabase
            .from('messages')
            .select('id, content')
            .in('id', ledgerIds);

          if (Array.isArray(ledgerRows) && ledgerRows.length > 0) {
            const hasEntries = ledgerRows.some((row: any) => {
              try {
                const parsed = typeof row.content === 'string' ? JSON.parse(row.content) : row.content;
                const logs = Array.isArray(parsed) ? parsed : (parsed?.logs || []);
                return Array.isArray(logs) && logs.length > 0;
              } catch {
                return false;
              }
            });
            if (hasEntries) return { unlocked: true };
          }

          return { unlocked: true };
        } else {
          // Check pplanCache first
          for (const tId of tenantIds) {
            const cached = pplanCache.get(`pplan_${tId}_${normUser}`);
            if (cached && cached.raw) {
              try {
                const raw = JSON.parse(cached.raw);
                const revStatus = raw?.metadata?.reviewStatus;
                const auditStatus = raw?.metadata?.internalAuditStatus;
                const managerDone = revStatus === 'Reviewed' || revStatus === 'Approved';
                const auditDone = auditStatus === 'Audited' || auditStatus === 'Pushed to DPMC' || auditStatus === 'Pushed to Moderation';
                return { unlocked: !!(managerDone && auditDone) };
              } catch {}
            }
          }

          const docId = `pplan_${tenantId}_${normUser}`;
          const { data, error } = await supabase
            .from('messages')
            .select('content')
            .eq('id', docId)
            .eq('message_type', 'pplan_list')
            .maybeSingle();

          if (error || !data || !data.content) {
            return { unlocked: false };
          }

          try {
            const raw = typeof data.content === 'string' ? JSON.parse(data.content) : data.content;
            const revStatus = raw?.metadata?.reviewStatus;
            const auditStatus = raw?.metadata?.internalAuditStatus;
            const managerDone = revStatus === 'Reviewed' || revStatus === 'Approved';
            const auditDone = auditStatus === 'Audited' || auditStatus === 'Pushed to DPMC' || auditStatus === 'Pushed to Moderation';
            return { unlocked: !!(managerDone && auditDone) };
          } catch {
            return { unlocked: false };
          }
        }
      });

      return res.json(result);
    } catch (e: any) {
      return res.json({ unlocked: false });
    }
  });

  app.get(["/api/tenant/:tenantId/team-pplans", "/api/tenant/:tenantId/team-plans"], async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const isMetadataOnly = req.query.metadata_only === 'true' || req.query.summary === 'true';
    const subordinateEmailsParam = (req.query.subordinateEmails as string || req.query.userEmails as string || '').toLowerCase().trim();
    const managerEmailParam = (req.query.managerEmail as string || '').toLowerCase().trim();
    try {
      const supabase = getSupabase();
      
      let tenantId = routeTenantId || 'nkangala_auto';
      let tenantIds = [tenantId];
      if (tenantId === 'nkangala_auto' || tenantId === 'tenant-229') {
        tenantIds = ['nkangala_auto', 'tenant-229'];
      }

      // 1. Build targeted ID filter if subordinate emails or manager email are specified
      let filterIds: string[] | null = null;
      let targetSubs: string[] = [];
      const usersList = await getConsolidatedUsersList(tenantId);

      if (subordinateEmailsParam) {
        targetSubs = subordinateEmailsParam.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
      }
      if (managerEmailParam) {
        try {
          const normMgr = managerEmailParam.toLowerCase().trim();
          
          const KNOWN_MGR_MAP: Record<string, string[]> = {
            'linkss': ['joubertm@nkangaladm.gov.za', 'tloujmt@nkangaladm.gov.za', 'singhn@nkangaladm.gov.za'],
            'singhn': ['marxc@nkangaladm.gov.za', 'nakapm@nkangaladm.gov.za', 'rachidimb@nkangaladm.gov.za', 'mokhabelagg@nkangaladm.gov.za'],
            'joubertm': ['matsebulan@nkangaladm.gov.za', 'mathenjwabh@nkangaladm.gov.za'],
            'magampeas': [
              'giyasi-affulph@nkangaladm.gov.za', 'sibanyonimj@nkangaladm.gov.za', 'singorl@nkangaladm.gov.za',
              'mangenart@nkangaladm.gov.za', 'mbulawan@nkangaladm.gov.za', 'mkhabelanc@nkangaladm.gov.za',
              'mpanzal@nkangaladm.gov.za', 'mtswenism@nkangaladm.gov.za'
            ],
            'segamiy': ['nkosiwm@nkangaladm.gov.za', 'mochitelaso@nkangaladm.gov.za'],
            'tloujmt': [
              'rakauj@nkangaladm.gov.za', 'gakwamf@nkangaladm.gov.za', 'mahlangude@nkangaladm.gov.za',
              'mankopanamm@nkangaladm.gov.za', 'moepis@nkangaladm.gov.za', 'molefeki@nkangaladm.gov.za',
              'mthimunyepm@nkangaladm.gov.za'
            ],
            'fenyanep': [
              'dlaminiss@nkangaladm.gov.za', 'khozahf@nkangaladm.gov.za', 'mafodim@nkangaladm.gov.za',
              'mashilesm@nkangaladm.gov.za', 'moreroaml@nkangaladm.gov.za', 'thumbathiamd@nkangaladm.gov.za',
              'mthethwanm@nkangaladm.gov.za'
            ],
            'khuboni': ['lukhelema@nkangaladm.gov.za', 'sakisd@nkangaladm.gov.za'],
            'shabangusm': ['zulune@nkangaladm.gov.za', 'nsibandenp@nkangaladm.gov.za'],
            'nparbhoo': ['mathibelanmb@nkangaladm.gov.za', 'ngomatkr@nkangaladm.gov.za', 'skosanast@nkangaladm.gov.za', 'motebupp@nkangaladm.gov.za'],
            'parbhoon': ['mathibelanmb@nkangaladm.gov.za', 'ngomatkr@nkangaladm.gov.za', 'skosanast@nkangaladm.gov.za', 'motebupp@nkangaladm.gov.za'],
            'nkosiso': ['sukazip@nkangaladm.gov.za', 'xabang@nkangaladm.gov.za'],
            'nkosis': ['wakenis@nkangaladm.gov.za', 'mokgolomothome@nkangaladm.gov.za'],
            'nkosije': ['myenispl@nkangaladm.gov.za'],
            'motshwenenm': ['mazwitc@nkangaladm.gov.za'],
            'mahlanguml': ['shabangusm@nkangaladm.gov.za', 'shabangugm@nkangaladm.gov.za']
          };

          const normMgrUser = normMgr.split('@')[0];
          for (const [key, subs] of Object.entries(KNOWN_MGR_MAP)) {
            const keyNorm = key.toLowerCase().trim();
            const keyUser = keyNorm.split('@')[0];
            if (normMgr === keyNorm || normMgrUser === keyUser) {
              subs.forEach(s => {
                if (!targetSubs.includes(s)) targetSubs.push(s);
              });
            }
          }

          // Include universal subordinateEmails computed on the manager's consolidated user record
          const mgrProfile = usersList.find((u: any) => (u.email || '').toLowerCase().trim() === normMgr);
          if (mgrProfile && Array.isArray(mgrProfile.subordinateEmails)) {
            mgrProfile.subordinateEmails.forEach((s: string) => {
              const cleanS = (s || '').toLowerCase().trim();
              if (cleanS && !targetSubs.includes(cleanS)) targetSubs.push(cleanS);
            });
          }

          const mgrFullName = (mgrProfile?.fullName || '').toLowerCase().trim().replace(/['"\.,]/g, ' ').replace(/\s+/g, ' ').trim();
          const mgrTokens = mgrFullName.split(' ').filter(Boolean);

          const dynamicSubs = usersList
            .filter((u: any) => {
              const uEmail = (u.email || '').toLowerCase().trim();
              if (!uEmail || uEmail === normMgr) return false;
              const mEmail = (u.managerEmail || '').toLowerCase().trim();
              if (mEmail) {
                const mEmailUser = mEmail.split('@')[0];
                if (mEmail === normMgr || mEmailUser === normMgrUser) {
                  return true;
                }
                // If the employee already has an explicit different manager email, never cross-assign
                return false;
              }
              const mName = (u.manager || u.reportTo || '').toLowerCase().trim().replace(/['"\.,]/g, ' ').replace(/\s+/g, ' ').trim();
              if (!mName) return false;
              if (mgrFullName && (mName === mgrFullName || mName.includes(mgrFullName) || mgrFullName.includes(mName))) {
                return true;
              }
              if (mgrTokens.length >= 2) {
                const mTokens = mName.split(' ').filter(Boolean);
                if (mTokens.length >= 2 && mTokens[0] === mgrTokens[0] && mTokens[mTokens.length - 1] === mgrTokens[mgrTokens.length - 1]) {
                  // If last name is 'nkosi', verify first name matches beyond just the single initial to avoid Siphesihle / Sanele collision
                  if (mTokens[mTokens.length - 1] === 'nkosi' && mTokens[0] !== mgrTokens[0]) {
                    return false;
                  }
                  return true;
                }
              }
              const mgrPrefix = normMgr.split('@')[0].replace(/[^a-z]/g, '');
              const mClean = mName.replace(/[^a-z]/g, '');
              return (mgrPrefix.length >= 4 && mClean.includes(mgrPrefix)) ||
                (normMgr.includes('links') && mName.includes('links')) ||
                (normMgr.includes('singh') && mName.includes('singh')) ||
                (normMgr.includes('joubert') && mName.includes('joubert')) ||
                (normMgr.includes('magampe') && mName.includes('magampe')) ||
                (normMgr.includes('segami') && mName.includes('segami')) ||
                (normMgr.includes('tlou') && mName.includes('tlou')) ||
                (normMgr.includes('fenyane') && mName.includes('fenyane'));
            })
            .map((u: any) => (u.email || '').toLowerCase().trim())
            .filter(Boolean);

          dynamicSubs.forEach((s: string) => {
            if (!targetSubs.includes(s)) targetSubs.push(s);
          });
        } catch (e) {
          console.warn("Could not lookup subordinates by managerEmail:", e);
        }
      }

      if (targetSubs.length > 0) {
        const idSet = new Set<string>();
        for (const sub of targetSubs) {
          const origCaseUser = usersList.find((u: any) => (u.email || '').toLowerCase().trim() === sub);
          const candidateEmails = Array.from(new Set([sub, origCaseUser?.email?.trim()].filter(Boolean)));
          for (const cEmail of candidateEmails) {
            for (const tId of tenantIds) {
              idSet.add(`pplan_${tId}_${cEmail}`);
              idSet.add(`kpis_${tId}_${cEmail}`);
            }
            idSet.add(`pplan_global_${cEmail}`);
            idSet.add(`kpis_global_${cEmail}`);
          }
        }
        filterIds = Array.from(idSet);
      }

      // Check micro-cache and coalesce concurrent requests (invalidated automatically whenever any pplan or kpi is saved)
      const cacheKey = `team_pplans_${tenantId}_${isMetadataOnly}_${targetSubs.join('_') || 'all'}`;
      if (req.query.force === 'true') {
        memoryCache.delete(cacheKey);
      }

      const result = await fetchWithCoalescing(cacheKey, 20000, async () => {
        let query = supabase
          .from('messages')
          .select('id, tenant_id, sender_email, content, created_at, message_type');

        if (filterIds && filterIds.length > 0) {
          query = query.in('id', filterIds);
        } else {
          query = query.eq('message_type', 'pplan_list').in('tenant_id', tenantIds);
        }

        const { data, error } = await query;

        if (error) {
          logSupabaseError("team-pplans", error);
          return { teamPlans: [] };
        }

        const allTenantPrefixes = [...tenantIds, 'global'];
        const kpisBySub = new Map<string, any[][]>();
        const pplanRows: any[] = [];

        for (const row of (data || [])) {
          const rowId = String(row.id || '');
          const isKpiRow = rowId.startsWith('kpis_') || row.message_type === 'kpis_list' || row.message_type === 'kpi_list';
          let userId = '';
          const prefixType = isKpiRow ? 'kpis_' : 'pplan_';
          const foundTenantId = allTenantPrefixes.find(tId => rowId.startsWith(`${prefixType}${tId}_`));
          if (foundTenantId) {
            userId = rowId.substring(`${prefixType}${foundTenantId}_`.length);
          } else {
            const parts = rowId.split('_');
            userId = parts[parts.length - 1] || row.sender_email || '';
          }
          userId = (normalizeNkangalaEmail(userId.toLowerCase().trim()) || userId.toLowerCase().trim());

          if (isKpiRow) {
            if (row.content && userId) {
              try {
                const rawKpi = typeof row.content === 'string' ? JSON.parse(row.content) : row.content;
                const kList = Array.isArray(rawKpi) ? rawKpi : (rawKpi?.kpis || rawKpi?.items || rawKpi?.rows || []);
                if (Array.isArray(kList) && kList.length > 0) {
                  if (!kpisBySub.has(userId)) kpisBySub.set(userId, []);
                  kpisBySub.get(userId)!.push(kList);
                }
              } catch (e) {}
            }
          } else {
            pplanRows.push({ ...row, _resolvedUserId: userId });
          }
        }

        const stripHeavyBlobsFromItem = (it: any) => {
          if (!it) return it;
          const stripDocs = (docs?: any[]) => Array.isArray(docs) ? docs.map(d => {
            if (!d) return d;
            const safeUrl = (typeof d.dataUrl === 'string' && d.dataUrl.startsWith('/api/poe/blob/'))
              ? d.dataUrl
              : ((typeof d.url === 'string' && d.url.startsWith('/api/poe/blob/')) ? d.url : undefined);
            return {
              id: d.id,
              name: d.name,
              size: d.size,
              mimeType: d.mimeType,
              uploadedAt: d.uploadedAt,
              uploadedBy: d.uploadedBy,
              ...(safeUrl ? { dataUrl: safeUrl, url: safeUrl } : {})
            };
          }) : [];
          const { poeFileBase64, ...rest } = it;
          return {
            ...rest,
            q1PoeDocs: stripDocs(it.q1PoeDocs),
            q2PoeDocs: stripDocs(it.q2PoeDocs),
            q3PoeDocs: stripDocs(it.q3PoeDocs),
            q4PoeDocs: stripDocs(it.q4PoeDocs),
            annualPoeDocs: stripDocs(it.annualPoeDocs),
            midtermPoeDocs: stripDocs(it.midtermPoeDocs)
          };
        };

        const isSyntheticTeamKpi = (it: any): boolean => {
          if (!it) return true;
          const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase().trim();
          const goal = String(it.strategicGoal || it.priorityIssue || '').toLowerCase().trim();
          return (
            desc.startsWith('achieve target deliverable kpi-') ||
            desc.startsWith('achieve 100% statutory compliance and operational targets for') ||
            desc.startsWith('ensure 100% adherence to departmental budget control and mfma expenditure guidelines in') ||
            desc.includes('maintain 100% resolution of public service queries and operational requests within prescribed slas') ||
            desc.includes('complete all mandatory individual performance reviews and personal development plan (pdp) targets for 2026/2027') ||
            goal.includes('aspirant local municipal aligned performance objective') ||
            goal.includes('local statutory priority target')
          );
        };

        const teamPlans = pplanRows
          .map((row: any) => {
            const userId = row._resolvedUserId;

            let planObj: any = { metadata: {}, items: [] };
            if (row.content) {
              try {
                const rawObj = typeof row.content === 'string' ? JSON.parse(row.content) : row.content;
                planObj = Array.isArray(rawObj) ? { metadata: {}, items: rawObj } : rawObj;
                if (planObj && Array.isArray(planObj.items)) {
                  const nonSynth = planObj.items.filter((it: any) => !isSyntheticTeamKpi(it));
                  const baseList = nonSynth.length > 0 ? nonSynth : planObj.items;
                  planObj.items = baseList.map((it: any) => sanitizePplanItem(it, userId));
                  if (userId.toLowerCase().includes('moepis')) {
                    planObj.items = planObj.items.filter((it: any) => {
                      const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
                      const id = String(it.id || '').toLowerCase();
                      const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
                      if (no === '25' || no === '26') return false;
                      if (id.endsWith('-25') || id.endsWith('-26')) return false;
                      if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
                      return true;
                    });
                  }
                  if (userId.toLowerCase().includes('matherets')) {
                    planObj.items = planObj.items.filter((it: any) => {
                      const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
                      const id = String(it.id || '').toLowerCase();
                      const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
                      if (no === '13' || no === '14' || no === '15') return false;
                      if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
                      if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
                      return true;
                    });
                  }
                  if (userId.toLowerCase().includes('nakapm')) {
                    planObj.items = planObj.items.filter((it: any) => {
                      const id = String(it.id || '').toLowerCase();
                      const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
                      if (id.startsWith('kpi-sync-178970925981')) return false;
                      if (desc.includes('staff vacancy rate') || desc.includes('vacant posts filled') || desc.includes('workplace skills plan') || desc.includes('suspended officials') || desc.includes('active suspensions') || desc.includes('declared their financial interests')) return false;
                      return true;
                    });
                  }
                  if (isMetadataOnly) {
                    planObj.items = planObj.items.map(stripHeavyBlobsFromItem);
                  }
                }
              } catch (e) {}
            }

            return {
              userId,
              tenantId: row.tenant_id,
              createdAt: row.created_at,
              plan: planObj
            };
          });

        // Priority calculation: Canonical tenant-229 / Fred-extracted / real KPIs / newest documents take priority over stale copies
        const getPlanSubmissionPriority = (tp: any): number => {
          if (!tp || !tp.plan) return 0;
          const items = Array.isArray(tp.plan.items) ? tp.plan.items : [];
          const realItemsCount = items.filter((it: any) => !isSyntheticTeamKpi(it)).length;

          let score = 0;
          if (realItemsCount > 0) score += 100000;
          if (tp.tenantId === 'tenant-229') score += 50000;
          else if (tp.tenantId === 'nkangala_auto') score += 25000;

          if (tp.plan.metadata?._isFredExtracted) score += 20000;

          score += Math.min(realItemsCount, 500);

          return score;
        };

        // Group by userId, pick newest/canonical plan, and merge items/POEs across all pplan_ and kpis_ rows for that subordinate
        const groupedBySub = new Map<string, any[]>();
        for (const tp of teamPlans) {
          if (!tp.userId) continue;
          if (!groupedBySub.has(tp.userId)) groupedBySub.set(tp.userId, []);
          groupedBySub.get(tp.userId)!.push(tp);
        }

        const dedupedMap = new Map<string, any>();
        for (const [subId, candidates] of groupedBySub.entries()) {
          candidates.sort((a, b) => {
            const tA = new Date(a.plan?.metadata?._pushedAt || a.plan?.metadata?.updatedAt || a.createdAt || 0).getTime();
            const tB = new Date(b.plan?.metadata?._pushedAt || b.plan?.metadata?.updatedAt || b.createdAt || 0).getTime();
            const aHasReal = (Array.isArray(a.plan?.items) && a.plan.items.some((it: any) => !isSyntheticTeamKpi(it))) ? 1 : 0;
            const bHasReal = (Array.isArray(b.plan?.items) && b.plan.items.some((it: any) => !isSyntheticTeamKpi(it))) ? 1 : 0;
            if (bHasReal !== aHasReal) return bHasReal - aHasReal;
            if (tB !== tA) return tB - tA;
            const sA = getPlanSubmissionPriority(a);
            const sB = getPlanSubmissionPriority(b);
            return sB - sA;
          });

          const best = candidates[0];
          if (best.plan) {
            if (best.plan.metadata && best.plan.metadata._isCleared) {
              best.plan.items = [];
            } else {
              const secondaryLists: any[][] = [];
              for (let i = 1; i < candidates.length; i++) {
                if (candidates[i].plan?.metadata?._isCleared) continue;
                const cItems = (candidates[i].plan?.items || []).filter((it: any) => !isSyntheticTeamKpi(it));
                if (cItems.length > 0) {
                  secondaryLists.push(cItems);
                }
              }
              for (const coOwnerEmail of getKhumaloNkosiAliases(subId)) {
                if (coOwnerEmail !== subId && groupedBySub.has(coOwnerEmail)) {
                  for (const coCand of groupedBySub.get(coOwnerEmail)!) {
                    if (coCand.plan?.metadata?._isCleared) continue;
                    const coItems = (coCand.plan?.items || []).filter((it: any) => !isSyntheticTeamKpi(it));
                    if (coItems.length > 0) secondaryLists.push(coItems);
                  }
                }
              }
              const subKpiLists = kpisBySub.get(subId);
              if (subKpiLists && subKpiLists.length > 0) {
                for (const kl of subKpiLists) {
                  const cleanKl = kl.filter((it: any) => !isSyntheticTeamKpi(it));
                  if (cleanKl.length > 0) secondaryLists.push(cleanKl);
                }
              }
              if (secondaryLists.length > 0) {
                const baseList = best.plan.items || [];
                const merged = mergePlanItemsWithSecondary(baseList, secondaryLists, baseList.length === 0).map((it: any) => sanitizePplanItem(it, subId));
                best.plan.items = isMetadataOnly ? merged.map(stripHeavyBlobsFromItem) : merged;
              }
              if (best.plan.metadata && Array.isArray(best.plan.items)) {
                const genuinelySubmittedIds = new Set(
                  best.plan.items
                    .filter((it: any) =>
                      it.reviewStatus === 'Submitted for Approval' ||
                      it.reviewStatus === 'Submitted for Review' ||
                      it.reviewStatus === 'Submitted' ||
                      it.reviewStatus === 'Approved' ||
                      it.reviewStatus === 'Reviewed' ||
                      it.reviewStatus === 'Revision Required' ||
                      it.reviewStatus === 'Dispatched to Audit' ||
                      it.reviewStatus === 'Dispatched to Internal Audit'
                    )
                    .map((it: any) => String(it.id || ''))
                );
                if (Array.isArray(best.plan.metadata.submittedKpiIds)) {
                  best.plan.metadata.submittedKpiIds = best.plan.metadata.submittedKpiIds.filter((id: any) =>
                    genuinelySubmittedIds.has(String(id || ''))
                  );
                }
                if (
                  (best.plan.metadata.reviewStatus === 'Submitted for Approval' ||
                    best.plan.metadata.reviewStatus === 'Submitted for Review' ||
                    best.plan.metadata.reviewStatus === 'Submitted') &&
                  genuinelySubmittedIds.size === 0
                ) {
                  best.plan.metadata.reviewStatus = 'Draft';
                }
              }
            }
          }
          dedupedMap.set(subId, best);
        }

        // Ensure every subordinate in targetSubs (or with kpis_ rows) has a complete plan entry with live profile metadata and real KPIs (never generating fake KPIs)
        const allTargetSubIds = Array.from(new Set([...targetSubs, ...Array.from(kpisBySub.keys())]));
        for (const subId of allTargetSubIds) {
          const uProfile = usersList.find((u: any) => (u.email || '').toLowerCase().trim() === subId);
          let entry = dedupedMap.get(subId);
          const isSubCleared = Boolean(entry?.plan?.metadata?._isCleared);

          if (!entry || !entry.plan || (!isSubCleared && (!Array.isArray(entry.plan.items) || entry.plan.items.length === 0))) {
            const subKpiLists = isSubCleared ? [] : (kpisBySub.get(subId) || []);
            let initialItems: any[] = [];
            if (subKpiLists.length > 0) {
              const mergedKpis = mergePlanItemsWithSecondary(subKpiLists[0], subKpiLists.slice(1), false)
                .filter((it: any) => !isSyntheticTeamKpi(it))
                .map((it: any) => sanitizePplanItem(it, subId));
              initialItems = isMetadataOnly ? mergedKpis.map(stripHeavyBlobsFromItem) : mergedKpis;
            }
            entry = {
              userId: subId,
              tenantId: 'tenant-229',
              createdAt: new Date().toISOString(),
              plan: {
                metadata: {
                  ...(entry?.plan?.metadata || {}),
                  name: uProfile?.fullName || entry?.plan?.metadata?.name || subId.split('@')[0],
                  position: uProfile?.jobFunction || entry?.plan?.metadata?.position || 'Municipal Official',
                  department: uProfile?.department || entry?.plan?.metadata?.department || 'Municipal Administration',
                  manager: uProfile?.manager || entry?.plan?.metadata?.manager || '',
                  managerEmail: uProfile?.managerEmail || entry?.plan?.metadata?.managerEmail || '',
                  reportTo: uProfile?.reportTo || uProfile?.manager || entry?.plan?.metadata?.reportTo || '',
                  financialYear: '2026/2027'
                },
                items: initialItems
              }
            };
            dedupedMap.set(subId, entry);
          } else if (uProfile && entry.plan) {
            if (!entry.plan.metadata) entry.plan.metadata = {};
            if (uProfile.fullName && (!entry.plan.metadata.name || entry.plan.metadata.name.includes('Placeholder'))) {
              entry.plan.metadata.name = uProfile.fullName;
            }
            if (uProfile.jobFunction && !entry.plan.metadata.position) {
              entry.plan.metadata.position = uProfile.jobFunction;
            }
            if (uProfile.department && !entry.plan.metadata.department) {
              entry.plan.metadata.department = uProfile.department;
            }
            if (uProfile.manager) {
              if (subId.includes('zulune') || subId.includes('nsibande') || !entry.plan.metadata.manager) {
                entry.plan.metadata.manager = uProfile.manager;
              }
            }
            if (uProfile.managerEmail) {
              if (subId.includes('zulune') || subId.includes('nsibande') || !entry.plan.metadata.managerEmail) {
                entry.plan.metadata.managerEmail = uProfile.managerEmail;
              }
            }
          }
        }

        const finalTeamPlans = Array.from(dedupedMap.values());
        return { teamPlans: finalTeamPlans };
      });

      return res.json(result);
    } catch (err: any) {
      console.error("team-pplans load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/tenant/:tenantId/clear-subordinates-ledger", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const { userIds } = req.body;
    try {
      const supabase = getSupabase();
      if (!supabase) throw new Error("Supabase is not initialized");
      if (!Array.isArray(userIds) || userIds.length === 0) {
        return res.json({ success: true, updatedCount: 0 });
      }

      let updatedCount = 0;
      let tenantId = routeTenantId || 'nkangala_auto';
      let tenantIds = [tenantId, 'global'];
      if (tenantId === 'nkangala_auto' || tenantId === 'tenant-229') {
        tenantIds = ['nkangala_auto', 'tenant-229', 'global'];
      }

      // Query messages of type pplan_list and kpis_list for the relevant tenants
      const { data, error } = await supabase
        .from('messages')
        .select('id, tenant_id, sender_email, content, message_type')
        .in('message_type', ['pplan_list', 'kpis_list'])
        .in('tenant_id', tenantIds);

      if (error) throw error;

      const nowIso = new Date().toISOString();
      for (const row of data || []) {
        // Extract userId/email
        let userId = '';
        const prefix = row.id.startsWith('kpis_') ? 'kpis_' : 'pplan_';
        const foundTenantId = tenantIds.find(tId => row.id.startsWith(`${prefix}${tId}_`));
        if (foundTenantId) {
          userId = row.id.substring(`${prefix}${foundTenantId}_`.length);
        } else {
          const parts = row.id.split('_');
          userId = parts[parts.length - 1] || row.sender_email || '';
        }

        const normUser = userId.toLowerCase().trim();
        const matchesUser = userIds.some((u: any) => {
          const normU = u.toLowerCase().trim();
          return normU === normUser || row.id.toLowerCase().includes(normU);
        });

        if (matchesUser) {
          let content = typeof row.content === 'string' ? JSON.parse(row.content) : row.content;
          if (content) {
            let changed = false;
            if (content.metadata) {
              content.metadata.reviewStatus = 'Draft';
              content.metadata.internalAuditStatus = 'Draft';
              content.metadata.submittedKpiIds = [];
              delete content.metadata.lastSubmittedKpiId;
              content.metadata.updatedAt = nowIso;
              changed = true;
            }
            const itemList = Array.isArray(content.items) ? content.items : (Array.isArray(content.kpis) ? content.kpis : null);
            if (Array.isArray(itemList)) {
              itemList.forEach((item: any) => {
                item.reviewStatus = 'Draft';
                delete item.reviewApprovalStatus;
                delete item.internalAuditStatus;
                delete item.internalAuditRating;
                delete item.internalAuditComment;
              });
              changed = true;
            }
            if (changed) {
              const updatedContentStr = typeof row.content === 'string' ? JSON.stringify(content) : content;
              await supabase.from('messages').update({ content: updatedContentStr, created_at: nowIso }).eq('id', row.id);
              pplanCache.delete(row.id);
              kpisCache.delete(row.id);
              updatedCount++;
            }
          }
        }
      }

      pplanCache.clear();
      kpisCache.clear();
      for (const k of memoryCache.keys()) {
        if (k.startsWith('team_pplans_') || k.startsWith('reports_unlock_')) memoryCache.delete(k);
      }
      return res.json({ success: true, updatedCount });
    } catch (err: any) {
      console.error("clear-subordinates-ledger exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

