  app.post("/api/tenant/:tenantId/pplan", async (req, res) => {
    const { tenantId: routeTenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const userId = normalizeNkangalaEmail(rawUserId) || rawUserId;
    const { metadata, items } = req.body || {};
    try {
      const supabase = getSupabase();
      const tenantId = await resolveTenantId(routeTenantId, userId);
      
      const targetUsers = getKhumaloNkosiAliases(userId);
      if (userId.includes('mahlanguml') || userId.includes('mahlangulm') || userId.includes('mandlaml')) {
        if (!targetUsers.includes('mahlanguml@nkangaladm.gov.za')) targetUsers.push('mahlanguml@nkangaladm.gov.za');
        if (!targetUsers.includes('mahlangulm@nkangaladm.gov.za')) targetUsers.push('mahlangulm@nkangaladm.gov.za');
      }

      const syncTenants = (tenantId === 'tenant-229' || tenantId === 'nkangala_auto' || userId.includes('@nkangaladm.gov.za'))
        ? ['tenant-229', 'nkangala_auto', 'global']
        : [tenantId, 'global'];

      const isSyntheticPostItem = (it: any): boolean => {
        if (!it) return true;
        const desc = String(it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase().trim();
        const goal = String(it.strategicGoal || it.priorityIssue || '').toLowerCase().trim();
        return (
          desc.startsWith('achieve target deliverable kpi-') ||
          desc.startsWith('achieve 100% statutory compliance and operational targets for') ||
          desc.startsWith('ensure 100% adherence to departmental budget control and mfma expenditure guidelines in') ||
          desc.includes('maintain 100% resolution of public service queries and operational requests within prescribed slas') ||
          desc.includes('complete all mandatory individual performance reviews and personal development plan (pdp) targets for 2026/2027') ||
          goal.includes('aspirant local municipal aligned performance objective') ||
          goal.includes('local statutory priority target')
        );
      };

      let sanitizedItems = Array.isArray(items) ? items.map((it: any) => sanitizePplanItem(it, userId)) : [];
      const nonSynthIncoming = sanitizedItems.filter((it: any) => !isSyntheticPostItem(it));
      if (nonSynthIncoming.length > 0) {
        sanitizedItems = nonSynthIncoming;
      }

      // Zero-Data-Loss Merge Protection: if the user already has a full real KPI plan in cache or Supabase,
      // never allow an accidental partial/synthetic payload to wipe out their other real KPIs or POE attachments,
      // while honoring explicit Clear Grid (_isCleared) and authoritative Fred / Planner Grid saves (_replacePlan / _allowItemDeletion).
      const isExplicitlyClearedPost = Boolean(metadata && metadata._isCleared === true);
      const isAuthoritativeReplacePost = Boolean(metadata && (metadata._replacePlan === true || metadata._allowItemDeletion === true));
      const isAuthoritativePoePost = Boolean(metadata && metadata._authoritativePoeUpdate === true);
      let existingParsedPlan: any = null;
      if (!isExplicitlyClearedPost) {
        const candidateKeys = Array.from(new Set(
          targetUsers.flatMap(u => [
            `pplan_tenant-229_${u}`,
            `pplan_${tenantId}_${u}`,
            `pplan_nkangala_auto_${u}`
          ])
        ));
        for (const ck of candidateKeys) {
          const cached = pplanCache.get(ck);
          if (cached && cached.raw) {
            try {
              const p = JSON.parse(cached.raw);
              if (p && Array.isArray(p.items) && p.items.some((it: any) => !isSyntheticPostItem(it))) {
                existingParsedPlan = p;
                break;
              }
            } catch (e) {}
          }
        }
        if (!existingParsedPlan && supabase && !(isAuthoritativeReplacePost && metadata && metadata._isFredExtracted === true)) {
          try {
            const dbLookupKeys = isTeamPmsCoOwner(userId)
              ? Array.from(new Set([
                  ...targetUsers.flatMap(u => [
                    `pplan_tenant-229_${u}`,
                    `team_evaluation_tenant-229_${u}`,
                    `team_pplan_tenant-229_${u}`
                  ])
                ]))
              : [
                  (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
                    ? `pplan_tenant-229_${userId}`
                    : `pplan_${tenantId}_${userId}`
                ];
            const exResult: any = await Promise.race([
              supabase
                .from('messages')
                .select('id, content')
                .in('id', dbLookupKeys),
              new Promise(resolve => setTimeout(() => resolve({ data: null, timedOut: true }), 4500))
            ]);
            const exRows = Array.isArray(exResult?.data) ? exResult.data : (exResult?.data ? [exResult.data] : []);
            const validPlans: any[][] = [];
            let firstMeta: any = null;
            for (const r of exRows) {
              if (r && r.content) {
                try {
                  const p = JSON.parse(r.content);
                  const rawItems = Array.isArray(p) ? p : (p?.items || p?.rows || []);
                  const realList = Array.isArray(rawItems) ? rawItems.filter((it: any) => !isSyntheticPostItem(it)) : [];
                  if (realList.length > 0) {
                    validPlans.push(realList);
                    if (!firstMeta && p?.metadata) firstMeta = p.metadata;
                  }
                } catch (e) {}
              }
            }
            if (validPlans.length > 0) {
              validPlans.sort((a, b) => b.length - a.length);
              const mergedExisting = validPlans.length > 1
                ? mergePlanItemsWithSecondary(validPlans[0], validPlans.slice(1), true, false)
                : validPlans[0];
              existingParsedPlan = { metadata: firstMeta || {}, items: mergedExisting };
            }
          } catch (e) {}
        }
      }

      if (isExplicitlyClearedPost) {
        sanitizedItems = [];
      } else if (existingParsedPlan && Array.isArray(existingParsedPlan.items) && existingParsedPlan.items.length > 0) {
        const existingRealItems = existingParsedPlan.items.filter((it: any) => !isSyntheticPostItem(it));
        if (existingRealItems.length > 0) {
          if (isAuthoritativeReplacePost) {
            // Authoritative replace from Fred Performance Plan Extractor or Annual Performance Planner Grid:
            // Keep ONLY the incoming KPIs (e.g. 15 extracted KPIs), while preserving any existing POE docs/scores on matching KPIs (appendUnmatched = false)
            if (sanitizedItems.length > 0) {
              sanitizedItems = mergePlanItemsWithSecondary(sanitizedItems, [existingRealItems], false, isAuthoritativePoePost).map((it: any) => sanitizePplanItem(it, userId));
            }
          } else if (sanitizedItems.length === 0 || sanitizedItems.every((it: any) => isSyntheticPostItem(it))) {
            // Reject accidental overwriting of real KPIs with empty or synthetic KPIs during evaluations
            sanitizedItems = existingRealItems;
          } else if (sanitizedItems.length < existingRealItems.length) {
            // Partial self-evaluation update: merge incoming updated KPIs into the existing full real KPI list (appendUnmatched = true)
            sanitizedItems = mergePlanItemsWithSecondary(sanitizedItems, [existingRealItems], true, isAuthoritativePoePost).map((it: any) => sanitizePplanItem(it, userId));
          } else {
            // Full list sent: when _authoritativePoeUpdate is true, honor POE deletions/replacements exactly without re-adding old POEs
            sanitizedItems = mergePlanItemsWithSecondary(sanitizedItems, [existingRealItems], false, isAuthoritativePoePost).map((it: any) => sanitizePplanItem(it, userId));
          }
        }
      }

      if (userId.toLowerCase().includes('moepis')) {
        sanitizedItems = sanitizedItems.filter((it: any) => {
          const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
          const id = String(it.id || '').toLowerCase();
          const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
          if (no === '25' || no === '26') return false;
          if (id.endsWith('-25') || id.endsWith('-26')) return false;
          if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
          return true;
        });
      }
      if (userId.toLowerCase().includes('matherets')) {
        sanitizedItems = sanitizedItems.filter((it: any) => {
          const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
          const id = String(it.id || '').toLowerCase();
          const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
          if (no === '13' || no === '14' || no === '15') return false;
          if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
          if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
          return true;
        });
      }

      // Enrich manager metadata from in-memory consolidated directory cache (non-blocking 0ms lookup to prevent 504 gateway timeouts)
      let uProfile: any = null;
      try {
        const cachedUsers = getCached<any[]>('consolidated_users_nkangala_master', 86400000) || cachedDiskUsersList || [];
        uProfile = cachedUsers.find((u: any) => (u.email || '').toLowerCase().trim() === userId.toLowerCase().trim());
        if (!cachedUsers.length) {
          setImmediate(() => {
            getConsolidatedUsersList(tenantId).catch(() => {});
          });
        }
      } catch (e) {}

      const nowIso = new Date().toISOString();
      const updatedMeta: any = {
        ...(existingParsedPlan?.metadata || {}),
        ...(metadata || {}),
        email: (metadata && metadata.email) || userId,
        updatedAt: nowIso
      };
      if (uProfile) {
        if (uProfile.fullName && !updatedMeta.name) updatedMeta.name = uProfile.fullName;
        if (uProfile.jobFunction && !updatedMeta.position) updatedMeta.position = uProfile.jobFunction;
        if (uProfile.department && !updatedMeta.department) updatedMeta.department = uProfile.department;
        if (uProfile.manager) updatedMeta.manager = uProfile.manager;
        if (uProfile.managerEmail) updatedMeta.managerEmail = uProfile.managerEmail;
        if (uProfile.reportTo || uProfile.manager) updatedMeta.reportTo = uProfile.reportTo || uProfile.manager;
      }
      if (isExplicitlyClearedPost || sanitizedItems.length === 0) {
        updatedMeta._isCleared = true;
        updatedMeta._isFredExtracted = false;
      } else {
        updatedMeta._isFredExtracted = true;
        updatedMeta._isCleared = false;
      }
      if (userId === 'joubertm@nkangaladm.gov.za' || userId === 'tloujmt@nkangaladm.gov.za') {
        updatedMeta.manager = 'Solly Links';
        updatedMeta.managerEmail = 'linkss@nkangaladm.gov.za';
        updatedMeta.reportTo = 'Solly Links';
      }

      // Offload any inline Base64 PoE files to dedicated `poe_blob_*` rows in Supabase before serializing the plan
      if (supabase && sanitizedItems.length > 0) {
        const { items: offloadedItems } = await offloadInlinePoeBlobs(sanitizedItems, userId, supabase);
        sanitizedItems = offloadedItems;
      }

      // Never duplicate `rows: sanitizedItems` inside the stored JSON payload (saves 50% storage & memory immediately)
      const payloadStr = JSON.stringify({ metadata: updatedMeta, items: sanitizedItems });
      const cleanKpiItems = sanitizedItems.map((it: any) => {
        const { poeFileBase64, q1PoeDocs, q2PoeDocs, q3PoeDocs, q4PoeDocs, annualPoeDocs, midtermPoeDocs, ...rest } = it;
        return rest;
      });
      const kpiPayloadStr = JSON.stringify({ kpis: cleanKpiItems });
      const lightweightMirrorPayloadStr = JSON.stringify({ metadata: updatedMeta, items: cleanKpiItems });
      const isTeamPms = isTeamPmsCoOwner(userId);

      // Always populate local in-memory caches across all candidate tenant buckets for immediate 0ms UI consistency
      const nowMs = Date.now();
      for (const u of targetUsers) {
        for (const tId of syncTenants) {
          pplanCache.set(`pplan_${tId}_${u}`, { raw: payloadStr, timestamp: nowMs });
          kpisCache.set(`kpis_${tId}_${u}`, { raw: kpiPayloadStr, timestamp: nowMs });
          if (isTeamPms) {
            pplanCache.set(`team_pplan_${tId}_${u}`, { raw: payloadStr, timestamp: nowMs });
            pplanCache.set(`team_pplan_${tId}_all`, { raw: payloadStr, timestamp: nowMs });
          }
        }
      }

      if (supabase) {
        const canonicalTenant = (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
          ? 'tenant-229'
          : tenantId;

        const primaryRows: any[] = [];
        const secondaryRows: any[] = [];
        for (const u of targetUsers) {
          for (const tId of syncTenants) {
            if (tId === canonicalTenant) {
              primaryRows.push({
                id: `pplan_${tId}_${u}`,
                tenant_id: tId,
                sender_id: 'pplan_editor_tool',
                sender_email: 'pplan@system.local',
                sender_name: 'PPLAN Editor',
                content: payloadStr,
                message_type: 'pplan_list',
                created_at: nowIso
              });
              if (isTeamPms) {
                primaryRows.push({
                  id: `team_pplan_${tId}_${u}`,
                  tenant_id: tId,
                  sender_id: 'team_pplan_editor_tool',
                  sender_email: 'team_pplan@system.local',
                  sender_name: 'Team PPLAN Editor',
                  content: payloadStr,
                  message_type: 'team_pplan_list',
                  created_at: nowIso
                });
                primaryRows.push({
                  id: `team_evaluation_${tId}_${u}`,
                  tenant_id: tId,
                  sender_id: 'team_evaluation_editor',
                  sender_email: 'team_eval@system.local',
                  sender_name: 'Team Evaluation Editor',
                  content: payloadStr,
                  message_type: 'team_evaluation_doc',
                  created_at: nowIso
                });
              }
            } else {
              secondaryRows.push({
                id: `pplan_${tId}_${u}`,
                tenant_id: tId,
                sender_id: 'pplan_editor_tool',
                sender_email: 'pplan@system.local',
                sender_name: 'PPLAN Editor',
                content: lightweightMirrorPayloadStr,
                message_type: 'pplan_list',
                created_at: nowIso
              });
              if (isTeamPms) {
                secondaryRows.push({
                  id: `team_pplan_${tId}_${u}`,
                  tenant_id: tId,
                  sender_id: 'team_pplan_editor_tool',
                  sender_email: 'team_pplan@system.local',
                  sender_name: 'Team PPLAN Editor',
                  content: lightweightMirrorPayloadStr,
                  message_type: 'team_pplan_list',
                  created_at: nowIso
                });
                secondaryRows.push({
                  id: `team_evaluation_${tId}_${u}`,
                  tenant_id: tId,
                  sender_id: 'team_evaluation_editor',
                  sender_email: 'team_eval@system.local',
                  sender_name: 'Team Evaluation Editor',
                  content: lightweightMirrorPayloadStr,
                  message_type: 'team_evaluation_doc',
                  created_at: nowIso
                });
              }
            }
            secondaryRows.push({
              id: `kpis_${tId}_${u}`,
              tenant_id: tId,
              sender_id: 'kpi_manager_tool',
              sender_email: 'kpi@system.local',
              sender_name: 'KPI Manager',
              content: kpiPayloadStr,
              message_type: 'kpis_list',
              created_at: nowIso
            });
          }
        }
        if (isTeamPms) {
          primaryRows.push({
            id: `team_pplan_${canonicalTenant}_all`,
            tenant_id: canonicalTenant,
            sender_id: 'team_pplan_editor_tool',
            sender_email: 'team_pplan@system.local',
            sender_name: 'Team PPLAN Editor',
            content: payloadStr,
            message_type: 'team_pplan_list',
            created_at: nowIso
          });
          primaryRows.push({
            id: `team_evaluation_${canonicalTenant}_all`,
            tenant_id: canonicalTenant,
            sender_id: 'team_evaluation_editor',
            sender_email: 'team_eval@system.local',
            sender_name: 'Team Evaluation Editor',
            content: payloadStr,
            message_type: 'team_evaluation_doc',
            created_at: nowIso
          });
        }

        // Write canonical row first with full POE payload and generous timeout so large POE uploads never get cut off
        const primaryWritePromise = Promise.resolve(
          supabase.from('messages').upsert(primaryRows, { onConflict: 'id' })
        ).catch((sErr: any) => {
          console.warn(`[pplan primary canonical save warning]:`, sErr?.message || sErr);
        });

        await Promise.race([
          primaryWritePromise,
          new Promise(resolve => setTimeout(resolve, 15000))
        ]);

        // Mirror lightweight KPI metadata to secondary keys in background without blocking or duplicating Base64 blobs
        setImmediate(() => {
          Promise.resolve(
            supabase.from('messages').upsert(secondaryRows, { onConflict: 'id' })
          ).catch(() => {});
        });
      }

      for (const k of memoryCache.keys()) {
        if (k.startsWith('team_pplans_') || k.startsWith('reports_unlock_')) memoryCache.delete(k);
      }
      invalidateCommandCenterCache();

      // Individual Performance Plan saves strictly and exclusively to the user's pplan document.
      res.json({ success: true, count: sanitizedItems.length });
    } catch (err: any) {
      console.error("pplan save exception:", err);
      res.status(500).json({ error: err?.message || err?.details || String(err) || "Failed to save performance plan" });
    }
  });

