  app.get("/api/tenant/:tenantId/kpis", async (req, res) => {
    const { tenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const userId = normalizeNkangalaEmail(rawUserId) || rawUserId;
    try {
      const supabase = getSupabase();
      const documentId = `kpis_${tenantId}_${userId}`;
      const fallbackDocIds = Array.from(new Set([
        documentId,
        `kpis_tenant-229_${userId}`,
        `kpis_nkangala_auto_${userId}`,
        `kpis_global_${userId}`
      ]));

      // Also inspect pplanCache / pplan documents so any manager approvals/rejections on pplan are reflected in /kpis
      const pplanLookupKeys = Array.from(new Set([
        `pplan_${tenantId}_${userId}`,
        `pplan_tenant-229_${userId}`,
        `pplan_nkangala_auto_${userId}`,
        `pplan_global_${userId}`
      ]));
      const pplanStatusOverlay = new Map<string, any>();
      let isPlanExplicitlyCleared = false;
      for (const pKey of pplanLookupKeys) {
        const cachedP = pplanCache.get(pKey);
        if (cachedP && cachedP.raw) {
          try {
            const pp = JSON.parse(cachedP.raw);
            if (pp?.metadata?._isCleared === true) {
              isPlanExplicitlyCleared = true;
            }
            const pItems = pp.items || pp.rows || [];
            if (Array.isArray(pItems)) {
              pItems.forEach((it: any) => {
                const kId = String(it.id || '').toLowerCase().trim();
                const kNo = String(it.kpiNo || '').toLowerCase().trim();
                if (kId) pplanStatusOverlay.set(`id:${kId}`, it);
                if (kNo) pplanStatusOverlay.set(`no:${kNo}`, it);
              });
            }
          } catch (e) {}
        }
      }
      if (isPlanExplicitlyCleared) {
        return res.json({ kpis: [] });
      }

      // Check in-memory kpisCache only for ultra-recent (< 2s) same-instance writes so cross-environment saves on AI Studio / Website always read fresh from Supabase
      let newestCachedKpi: { raw: string; timestamp: number } | null = null;
      for (const fId of fallbackDocIds) {
        const cachedK = kpisCache.get(fId);
        if (cachedK && cachedK.raw && (Date.now() - cachedK.timestamp < 2000)) {
          if (!newestCachedKpi || cachedK.timestamp >= newestCachedKpi.timestamp) {
            newestCachedKpi = cachedK;
          }
        }
      }
      if (newestCachedKpi) {
        try {
          const parsedCached = JSON.parse(newestCachedKpi.raw);
          let cachedList = Array.isArray(parsedCached) ? parsedCached : (parsedCached.kpis || parsedCached.items || []);
          if (Array.isArray(cachedList)) {
            cachedList = cachedList.map((it: any) => {
              const kId = String(it.id || '').toLowerCase().trim();
              const kNo = String(it.kpiNo || '').toLowerCase().trim();
              const overlay = (kId && pplanStatusOverlay.get(`id:${kId}`)) || (kNo && pplanStatusOverlay.get(`no:${kNo}`));
              const revStatus = overlay?.reviewStatus || it.reviewStatus;
              const isNonActionedRevStatus =
                revStatus === 'Submitted for Approval' ||
                revStatus === 'Submitted for Review' ||
                revStatus === 'Submitted' ||
                revStatus === 'Draft' ||
                revStatus === 'In Progress' ||
                revStatus === 'Draft / Resubmitting';
              const revApproval = isNonActionedRevStatus
                ? ''
                : (overlay?.reviewApprovalStatus || it.reviewApprovalStatus || (revStatus === 'Approved' ? 'Approved' : (revStatus === 'Revision Required' || revStatus === 'Rejected' ? 'Rejected' : undefined)));
              return {
                ...it,
                ...(revStatus ? { reviewStatus: revStatus } : {}),
                reviewApprovalStatus: revApproval || '',
                ...(overlay?.managerScore ? { managerScore: overlay.managerScore } : {}),
                ...(overlay?.reviewComment || overlay?.review ? { reviewComment: overlay.reviewComment || overlay.review } : {})
              };
            });
            return res.json({ kpis: cachedList });
          }
        } catch (e) {}
      }

      const { data: kpiRows } = await supabase
        .from('messages')
        .select('id, content, created_at')
        .in('id', fallbackDocIds);

      if (Array.isArray(kpiRows) && kpiRows.length > 0) {
        // Sort by newest created_at first so recently updated tenant buckets win
        kpiRows.sort((a: any, b: any) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime());
        for (const row of kpiRows) {
          if (row && row.content) {
            try {
              const parsed = JSON.parse(row.content);
              let kpiList = Array.isArray(parsed) ? parsed : (parsed.kpis || parsed.items || parsed.rows || []);
              if (userId.toLowerCase().includes('moepis')) {
                kpiList = kpiList.filter((it: any) => {
                  const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
                  const id = String(it.id || '').toLowerCase();
                  const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
                  if (no === '25' || no === '26') return false;
                  if (id.endsWith('-25') || id.endsWith('-26')) return false;
                  if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
                  return true;
                });
              }
              if (userId.toLowerCase().includes('matherets')) {
                kpiList = kpiList.filter((it: any) => {
                  const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
                  const id = String(it.id || '').toLowerCase();
                  const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
                  if (no === '13' || no === '14' || no === '15') return false;
                  if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
                  if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
                  return true;
                });
              }
              // If the newest kpis_ record was explicitly saved as empty, return empty rather than falling back to stale older buckets
              if (row.id === `kpis_tenant-229_${userId}` && Array.isArray(kpiList) && kpiList.length === 0) {
                return res.json({ kpis: [] });
              }
              if (kpiList.length > 0) {
                kpiList = kpiList.map((it: any) => {
                  const kId = String(it.id || '').toLowerCase().trim();
                  const kNo = String(it.kpiNo || '').toLowerCase().trim();
                  const overlay = (kId && pplanStatusOverlay.get(`id:${kId}`)) || (kNo && pplanStatusOverlay.get(`no:${kNo}`));
                  const revStatus = overlay?.reviewStatus || it.reviewStatus;
                  const isNonActionedRevStatus =
                    revStatus === 'Submitted for Approval' ||
                    revStatus === 'Submitted for Review' ||
                    revStatus === 'Submitted' ||
                    revStatus === 'Draft' ||
                    revStatus === 'In Progress' ||
                    revStatus === 'Draft / Resubmitting';
                  const revApproval = isNonActionedRevStatus
                    ? ''
                    : (overlay?.reviewApprovalStatus || it.reviewApprovalStatus || (revStatus === 'Approved' ? 'Approved' : (revStatus === 'Revision Required' || revStatus === 'Rejected' ? 'Rejected' : undefined)));
                  return {
                    ...it,
                    ...(revStatus ? { reviewStatus: revStatus } : {}),
                    reviewApprovalStatus: revApproval || '',
                    ...(overlay?.managerScore ? { managerScore: overlay.managerScore } : {}),
                    ...(overlay?.reviewComment || overlay?.review ? { reviewComment: overlay.reviewComment || overlay.review } : {})
                  };
                });
                return res.json({ kpis: kpiList });
              }
            } catch (parseErr) {
              console.error("Error parsing kpis JSON:", parseErr);
            }
          }
        }
      }

      // Fallback to pplan document if kpis document has 0 items
      const pplanDocId = `pplan_${tenantId}_${userId}`;
      const { data: pData } = await supabase.from('messages').select('content').eq('id', pplanDocId).maybeSingle();
      if (pData && pData.content) {
        try {
          const pp = JSON.parse(pData.content);
          if (pp?.metadata?._isCleared === true) {
            return res.json({ kpis: [] });
          }
          let pList = pp.rows || pp.items || pp.kpis || [];
          if (userId.toLowerCase().includes('moepis')) {
            pList = pList.filter((it: any) => {
              const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
              const id = String(it.id || '').toLowerCase();
              const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
              if (no === '25' || no === '26') return false;
              if (id.endsWith('-25') || id.endsWith('-26')) return false;
              if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
              return true;
            });
          }
          if (userId.toLowerCase().includes('matherets')) {
            pList = pList.filter((it: any) => {
              const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
              const id = String(it.id || '').toLowerCase();
              const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
              if (no === '13' || no === '14' || no === '15') return false;
              if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
              if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
              return true;
            });
          }
          if (pList.length > 0) {
            return res.json({ kpis: pList });
          }
        } catch(e) {}
      }

      if (userId.includes('shabangusm')) {
        const officialShabanguKpis = SHABANGUSM_OFFICIAL_KPIS.map((k, i) => ({
          id: `kpi-shabangu-${i + 1}`,
          kpiNo: k["kpi no"],
          kpi: k["kpi description"],
          target: k["annual target"] || '100%',
          annualTarget: k["annual target"] || '100%',
          q1Target: k["1st qtr target"],
          q2Target: k["2nd qtr target"],
          q3Target: k["3rd qtr target"],
          q4Target: k["4th qtr target"],
          weight: parseFloat(k["%wt"]) || 5,
          weighting: k["%wt"],
          baseline: k["baseline"] || '',
          poe: k["poe"] || '',
          annualRequiredPoe: k["poe"] || '',
          kpa: k["functional kpa"] || k["kpa"] || '',
          budget: k["budget"] || 'OPEX'
        }));
        return res.json({ kpis: officialShabanguKpis });
      }

      return res.json({ kpis: [] });
    } catch (err: any) {
      console.error("KPIs load exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // 19. Save KPIs for a tenant
  app.post("/api/tenant/:tenantId/kpis", async (req, res) => {
    const { tenantId } = req.params;
    const rawUserId = req.query.userId ? String(req.query.userId).toLowerCase().trim() : 'default';
    const userId = normalizeNkangalaEmail(rawUserId) || rawUserId;
    const { kpis } = req.body;
    try {
      const supabase = getSupabase();
      let cleanKpis = Array.isArray(kpis) ? kpis : [];
      if (userId.toLowerCase().includes('moepis')) {
        cleanKpis = cleanKpis.filter((it: any) => {
          const no = String(it.kpiNo || '').replace(/[^0-9]/g, '');
          const id = String(it.id || '').toLowerCase();
          const desc = (it.kpi || it.description || it.desc || '').toLowerCase();
          if (no === '25' || no === '26') return false;
          if (id.endsWith('-25') || id.endsWith('-26')) return false;
          if (desc.includes('percentage of staff vacancy') || desc.includes('vacant posts filled')) return false;
          return true;
        });
      }
      if (userId.toLowerCase().includes('matherets')) {
        cleanKpis = cleanKpis.filter((it: any) => {
          const no = String(it.kpiNo || it['kpi no'] || '').replace(/[^0-9]/g, '');
          const id = String(it.id || '').toLowerCase();
          const desc = (it.kpi || it.description || it.desc || it['kpi description'] || '').toLowerCase();
          if (no === '13' || no === '14' || no === '15') return false;
          if (id.endsWith('-13') || id.endsWith('-14') || id.endsWith('-15')) return false;
          if (desc.includes('achieve target deliverable kpi-13') || desc.includes('achieve target deliverable kpi-14') || desc.includes('achieve target deliverable kpi-15')) return false;
          return true;
        });
      }
      if (supabase && cleanKpis.length > 0) {
        const { items: offloadedKpis } = await offloadInlinePoeBlobs(cleanKpis, userId, supabase);
        cleanKpis = offloadedKpis;
      }
      const payload = { kpis: cleanKpis };
      const payloadStr = JSON.stringify(payload);
      const canonicalTenant = (tenantId === 'nkangala_auto' || tenantId === 'tenant-229' || userId.includes('@nkangaladm.gov.za'))
        ? 'tenant-229'
        : tenantId;
      const primaryId = `kpis_${canonicalTenant}_${userId}`;
      const nowIso = new Date().toISOString();
      const nowMs = Date.now();

      const syncKpiTenants = Array.from(new Set([canonicalTenant, tenantId, 'nkangala_auto', 'global']));
      for (const tId of syncKpiTenants) {
        kpisCache.set(`kpis_${tId}_${userId}`, { raw: payloadStr, timestamp: nowMs });
      }

      const kpiBatchRows = syncKpiTenants.map(tId => ({
        id: `kpis_${tId}_${userId}`,
        tenant_id: tId,
        sender_id: 'kpi_manager_tool',
        sender_email: 'kpi@system.local',
        sender_name: 'KPI Manager',
        content: payloadStr,
        message_type: 'kpis_list',
        created_at: nowIso
      }));

      const kpiWritePromise = Promise.resolve(
        supabase
          .from('messages')
          .upsert(kpiBatchRows, { onConflict: 'id' })
      ).catch((err: any) => {
        console.warn("[kpis save warning]:", err?.message || err);
      });

      await Promise.race([
        kpiWritePromise,
        new Promise(resolve => setTimeout(resolve, 6000))
      ]);

      for (const k of memoryCache.keys()) {
        if (k.startsWith('team_pplans_')) memoryCache.delete(k);
      }
      
      res.json({ success: true });
    } catch (err: any) {
      console.error("KPIs save exception:", err);
      res.status(500).json({ error: err.message });
    }
  });

