  // Helper to resolve all @mzansiflow.co.za and @nkangaladm.gov.za contacts
  async function getSupportDirectoryContacts(tenantId: string = 'tenant-229') {
    const allUsers = await getConsolidatedUsersList(tenantId || 'tenant-229');
    const coreMzansiAdmins = [
      { email: 'mike@mzansiflow.co.za', fullName: 'Mike (Mzansi Flow Lead)', jobFunction: 'Global Administrator & Support Lead', department: 'Mzansi Flow Executive Support' },
      { email: 'audrey@mzansiflow.co.za', fullName: 'Audrey (Mzansi Flow)', jobFunction: 'Senior Support & PMS Specialist', department: 'Mzansi Flow Support' },
      { email: 'delphine@mzansiflow.co.za', fullName: 'Delphine (Mzansi Flow)', jobFunction: 'Global Administrator & Support Specialist', department: 'Mzansi Flow Support' },
      { email: 'ryanw@mzansiflow.co.za', fullName: 'Ryan W. (Mzansi Flow)', jobFunction: 'Technical Support Engineer', department: 'Mzansi Flow Engineering' },
      { email: 'bongani@mzansiflow.co.za', fullName: 'Bongani (Mzansi Flow)', jobFunction: 'Global Administrator & Support', department: 'Mzansi Flow Support' },
      { email: 'bonganim@mzansiflow.co.za', fullName: 'Bongani M. (Mzansi Flow)', jobFunction: 'Global Administrator & Support', department: 'Mzansi Flow Support' },
      { email: 'qiniso@mzansiflow.co.za', fullName: 'Qiniso (Mzansi Flow)', jobFunction: 'Support & Operations Specialist', department: 'Mzansi Flow Support' },
      { email: 'marlan@mzansiflow.co.za', fullName: 'Marlan (Mzansi Flow)', jobFunction: 'Systems & Support Specialist', department: 'Mzansi Flow Support' }
    ];

    const contactMap = new Map<string, any>();

    for (const admin of coreMzansiAdmins) {
      contactMap.set(admin.email.toLowerCase(), {
        id: `mf-${admin.email.toLowerCase()}`,
        fullName: admin.fullName,
        email: admin.email.toLowerCase(),
        jobFunction: admin.jobFunction,
        department: admin.department,
        domain: 'mzansiflow.co.za'
      });
    }

    for (const u of allUsers) {
      const email = String(u.email || '').toLowerCase().trim();
      if (!email || email.includes('demo') || email.startsWith('test.')) continue;
      if (email.endsWith('@mzansiflow.co.za') || email.endsWith('@nkangaladm.gov.za')) {
        const existing = contactMap.get(email);
        const domain = email.endsWith('@mzansiflow.co.za') ? 'mzansiflow.co.za' : 'nkangaladm.gov.za';
        contactMap.set(email, {
          id: u.id || existing?.id || email,
          fullName: existing?.fullName || u.fullName || u.full_name || email.split('@')[0],
          email,
          jobFunction: u.jobFunction || u.job_function || existing?.jobFunction || (domain === 'mzansiflow.co.za' ? 'Mzansi Flow Specialist' : 'Municipal Official'),
          department: u.department || existing?.department || (domain === 'mzansiflow.co.za' ? 'Mzansi Flow' : 'Nkangala District Municipality'),
          domain
        });
      }
    }

      return Array.from(contactMap.values());
  }

  // Helper to load all support tickets from Supabase
  async function loadAllSupportTicketsFromSupabase(): Promise<any[]> {
    const supabase = getSupabase();
    const ticketMap = new Map<string, any>();

    const { data: storeRow } = await supabase
      .from('messages')
      .select('content')
      .eq('id', 'support_tickets_store')
      .maybeSingle();

    if (storeRow?.content) {
      try {
        const parsed = JSON.parse(storeRow.content);
        if (Array.isArray(parsed)) {
          for (const t of parsed) {
            if (t && t.id) ticketMap.set(t.id, t);
          }
        }
      } catch (_) {}
    }

    const { data: itemRows } = await supabase
      .from('messages')
      .select('id, content, created_at')
      .eq('message_type', 'support_ticket_item')
      .order('created_at', { ascending: false })
      .limit(500);

    if (Array.isArray(itemRows)) {
      for (const r of itemRows) {
        try {
          const parsed = typeof r.content === 'string' ? JSON.parse(r.content) : r.content;
          if (parsed && parsed.id && !ticketMap.has(parsed.id)) {
            ticketMap.set(parsed.id, parsed);
          }
        } catch (_) {}
      }
    }

    const list = Array.from(ticketMap.values());
    list.sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());
    return list;
  }

  // Helper to dispatch support ticket email to all @mzansiflow.co.za users
  async function dispatchSupportTicketEmailsToMzansiFlow(ticket: any, mzansiEmails: string[]) {
    const supabase = getSupabase();
    const createdAt = new Date().toISOString();

    const emailSubject = `[Support Ticket ${ticket.ticketNumber}] [${ticket.priority} Priority] ${ticket.subject}`;
    const emailTextBody = [
      `MZANSI FLOW ENTERPRISE SUPPORT TICKET NOTIFICATION`,
      `===================================================`,
      `Support Ticket Number : ${ticket.ticketNumber}`,
      `Priority Level        : ${ticket.priority}`,
      `Affected Category     : ${ticket.category}`,
      `Status                : ${ticket.status}`,
      `Logged By             : ${ticket.reporterName} (${ticket.reporterEmail})`,
      `Department / Role     : ${ticket.reporterDepartment} — ${ticket.reporterJobTitle}`,
      `Timestamp             : ${new Date(ticket.createdAt).toLocaleString()}`,
      ``,
      `REPORTED ISSUE DETAILS:`,
      `-----------------------`,
      `${ticket.issue}`,
      ``,
      ticket.document
        ? `UPLOADED DOCUMENT ATTACHED: ${ticket.document.name} (${Math.round((ticket.document.size || 0) / 1024)} KB)`
        : `UPLOADED DOCUMENT: None attached`
    ].join('\n');

    const emailHtmlBody = `
      <div style="font-family: Arial, sans-serif; max-width: 680px; margin: 0 auto; background: #0f172a; color: #f8fafc; padding: 24px; border-radius: 12px; border: 1px solid #1e293b;">
        <div style="border-bottom: 1px solid #1e293b; padding-bottom: 16px; margin-bottom: 16px;">
          <span style="background: #059669; color: #ffffff; font-size: 11px; font-weight: bold; padding: 4px 10px; border-radius: 4px; text-transform: uppercase;">
            Support Ticket ${ticket.ticketNumber}
          </span>
          <span style="background: #334155; color: #f8fafc; font-size: 11px; font-weight: bold; padding: 4px 10px; border-radius: 4px; text-transform: uppercase; margin-left: 8px;">
            Priority: ${ticket.priority}
          </span>
          <h2 style="margin: 12px 0 4px; color: #ffffff; font-size: 18px;">${ticket.subject}</h2>
          <p style="margin: 0; color: #94a3b8; font-size: 12px;">
            Logged by <strong>${ticket.reporterName}</strong> (${ticket.reporterEmail}) • ${ticket.reporterDepartment}
          </p>
        </div>
        <div style="background: #020617; border: 1px solid #1e293b; border-radius: 8px; padding: 16px; margin-bottom: 16px;">
          <p style="margin: 0 0 8px; font-size: 11px; text-transform: uppercase; color: #10b981; font-weight: bold;">Issue Description</p>
          <p style="margin: 0; font-size: 13px; line-height: 1.6; color: #e2e8f0; white-space: pre-wrap;">${ticket.issue}</p>
        </div>
        ${
          ticket.document
            ? `<div style="background: #064e3b; border: 1px solid #059669; border-radius: 8px; padding: 12px; font-size: 12px; color: #ecfdf5;">
                <strong>Attached Uploaded Document:</strong> ${ticket.document.name} (${Math.round((ticket.document.size || 0) / 1024)} KB)
              </div>`
            : ''
        }
      </div>
    `;

    // 1. Deliver directly into the IPMS Inbox of all @mzansiflow.co.za users so it is immediately accessible with the uploaded document inside the platform
    try {
      const inboxMsgId = `ipms_msg_ticket_${ticket.ticketNumber}_${Date.now()}`;
      const inboxAttachments = ticket.document
        ? [
            {
              id: `att_${Date.now()}`,
              name: ticket.document.name,
              type: ticket.document.mimeType || 'application/octet-stream',
              size: ticket.document.size || 0,
              url: ticket.document.dataUrl,
              dataUrl: ticket.document.dataUrl
            }
          ]
        : [];

      const inboxMsgObj = {
        id: inboxMsgId,
        threadId: `thread_ticket_${ticket.ticketNumber}`,
        replyToId: null,
        tenantId: ticket.tenantId || 'tenant-229',
        senderEmail: ticket.reporterEmail,
        senderName: `${ticket.reporterName} (Support Ticket ${ticket.ticketNumber})`,
        senderJobTitle: ticket.reporterJobTitle || 'Municipal Official',
        recipientEmails: [...mzansiEmails, 'all@mzansiflow.co.za'],
        recipientNames: mzansiEmails.map(e => e.split('@')[0]),
        subject: emailSubject,
        body: emailTextBody,
        attachments: inboxAttachments,
        createdAt,
        readBy: [ticket.reporterEmail],
        starredBy: [],
        trashedBy: []
      };

      await supabase.from('messages').upsert({
        id: inboxMsgId,
        tenant_id: ticket.tenantId || 'tenant-229',
        sender_id: ticket.reporterEmail,
        sender_email: ticket.reporterEmail,
        sender_name: ticket.reporterName,
        content: JSON.stringify(inboxMsgObj),
        message_type: 'ipms_inbox_item',
        created_at: createdAt
      }, { onConflict: 'id' });

      const targetStores = ['tenant-229', 'global', 'nkangala_auto'];
      for (const tId of targetStores) {
        const { data: storeData } = await supabase
          .from('messages')
          .select('content')
          .eq('id', `ipms_inbox_store_${tId}`)
          .maybeSingle();

        let existingMessages: any[] = [];
        if (storeData?.content) {
          try {
            existingMessages = JSON.parse(storeData.content);
            if (!Array.isArray(existingMessages)) existingMessages = [];
          } catch (_) {
            existingMessages = [];
          }
        }
        existingMessages.unshift(inboxMsgObj);
        if (existingMessages.length > 1000) existingMessages = existingMessages.slice(0, 1000);

        await supabase.from('messages').upsert({
          id: `ipms_inbox_store_${tId}`,
          tenant_id: tId,
          sender_id: 'support_ticket_mailer',
          sender_email: ticket.reporterEmail,
          sender_name: 'Support Ticket Email Dispatcher',
          content: JSON.stringify(existingMessages),
          message_type: 'ipms_inbox_store',
          created_at: createdAt
        }, { onConflict: 'id' });
      }
    } catch (inboxErr) {
      console.warn("Support ticket IPMS inbox mirror notice:", inboxErr);
    }

    // 2. If RESEND_API_KEY is configured in environment variables, dispatch external emails with the uploaded document attachment via native fetch
    try {
      const resendApiKey = process.env.RESEND_API_KEY;
      if (resendApiKey && mzansiEmails.length > 0) {
        const resendAttachments: any[] = [];
        if (ticket.document?.dataUrl) {
          const base64Match = String(ticket.document.dataUrl).match(/^data:([^;]+);base64,(.+)$/);
          if (base64Match) {
            resendAttachments.push({
              filename: ticket.document.name || 'support_attachment',
              content: base64Match[2]
            });
          }
        }

        await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${resendApiKey}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            from: process.env.SMTP_FROM || 'Mzansi Flow Support Desk <support@mzansiflow.co.za>',
            to: mzansiEmails,
            reply_to: ticket.reporterEmail,
            subject: emailSubject,
            text: emailTextBody,
            html: emailHtmlBody,
            attachments: resendAttachments.length > 0 ? resendAttachments : undefined
          })
        });
      }
    } catch (emailErr) {
      console.warn("External email API dispatch notice (internal inbox & Supabase email log completed):", emailErr);
    }

    // 3. Persist email dispatch audit record in Supabase
    try {
      await supabase.from('messages').upsert({
        id: `support_email_dispatch_${ticket.ticketNumber}`,
        tenant_id: 'global',
        sender_id: ticket.reporterEmail,
        sender_email: ticket.reporterEmail,
        sender_name: ticket.reporterName,
        content: JSON.stringify({
          ticketNumber: ticket.ticketNumber,
          recipients: mzansiEmails,
          subject: emailSubject,
          priority: ticket.priority,
          issue: ticket.issue,
          hasDocument: Boolean(ticket.document),
          documentName: ticket.document?.name || null,
          dispatchedAt: createdAt
        }),
        message_type: 'support_ticket_email_dispatch',
        created_at: createdAt
      }, { onConflict: 'id' });
    } catch (_) {}
  }

  // Stream 2: Get Support Tickets
  app.get("/api/support/tickets", async (req, res) => {
    res.setHeader("Content-Type", "application/json");
    try {
      const userEmail = String(req.query.userEmail || '').toLowerCase().trim();
      const allTickets = await Promise.race([
        loadAllSupportTicketsFromSupabase(),
        new Promise<any[]>(resolve => setTimeout(() => resolve([]), 7000))
      ]);
      const isMzansi =
        userEmail.endsWith('@mzansiflow.co.za') ||
        userEmail.includes('@mzansiflow.co.za') ||
        userEmail === 'mike@massivedynamixdistributors.com';

      if (!userEmail) {
        return res.status(200).json({ tickets: [] });
      }

      const visibleTickets = isMzansi
        ? allTickets
        : allTickets.filter(t => String(t.reporterEmail || '').toLowerCase().trim() === userEmail);

      return res.status(200).json({ tickets: Array.isArray(visibleTickets) ? visibleTickets : [] });
    } catch (err: any) {
      console.error("GET /api/support/tickets error:", err);
      return res.status(200).json({ tickets: [], error: err.message });
    }
  });

  // Support Article Helpful / Feedback Collection Route
  app.post("/api/support/feedback", async (req, res) => {
    try {
      const { articleId, articleTitle, userEmail, isHelpful, feedbackText } = req.body || {};
      const supabase = getSupabase();
      const feedbackId = `supp_fb_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
      const doc = {
        id: feedbackId,
        articleId: articleId || 'general',
        articleTitle: articleTitle || 'General FAQ',
        userEmail: userEmail || 'anonymous',
        isHelpful: Boolean(isHelpful),
        feedbackText: feedbackText || '',
        createdAt: new Date().toISOString()
      };
      await supabase.from('messages').insert([{
        id: feedbackId,
        content: JSON.stringify(doc),
        sender_id: userEmail || 'support_system',
        conversation_id: 'support_article_feedback',
        created_at: new Date().toISOString()
      }]);
      return res.status(200).json({ success: true, feedback: doc });
    } catch (err: any) {
      console.error("POST /api/support/feedback error:", err);
      return res.status(200).json({ success: false, error: err.message });
    }
  });

  // Stream 2: Create Support Ticket, Generate Ticket Number & Email All @mzansiflow.co.za Users
  app.post("/api/support/tickets", async (req, res) => {
    try {
      const {
        tenantId,
        reporterEmail,
        reporterName,
        reporterDepartment,
        reporterJobTitle,
        subject,
        category,
        priority,
        issue,
        document
      } = req.body;

      if (!reporterEmail || !subject || !issue) {
        return res.status(400).json({ error: "Reporter email, ticket subject, and issue description are required." });
      }

      const supabase = getSupabase();
      const existingTickets = await loadAllSupportTicketsFromSupabase();
      const nextSeq = existingTickets.length + 1;
      const year = new Date().getFullYear();
      const ticketNumber = `TKT-NDM-${year}-${String(nextSeq).padStart(4, '0')}`;
      const ticketId = `ticket_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
      const createdAt = new Date().toISOString();

      // Gather all @mzansiflow.co.za users so every @mzansiflow.co.za account receives the email
      const contacts = await getSupportDirectoryContacts(tenantId || 'tenant-229');
      const mzansiEmails = Array.from(
        new Set(
          contacts
            .filter(c => String(c.email || '').toLowerCase().endsWith('@mzansiflow.co.za'))
            .map(c => String(c.email).toLowerCase().trim())
        )
      );

      const newTicket = {
        id: ticketId,
        ticketNumber,
        tenantId: tenantId || 'tenant-229',
        reporterEmail: String(reporterEmail).toLowerCase().trim(),
        reporterName: reporterName || String(reporterEmail).split('@')[0],
        reporterDepartment: reporterDepartment || 'Nkangala District Municipality',
        reporterJobTitle: reporterJobTitle || 'Municipal Official',
        subject: String(subject).trim(),
        category: category || 'General System Support',
        priority: priority || 'High',
        issue: String(issue).trim(),
        status: 'Open',
        document: document || null,
        notifiedRecipients: mzansiEmails,
        emailDispatchedAt: createdAt,
        createdAt,
        updatedAt: createdAt,
        comments: []
      };

      // 1. Persist individual ticket row in Supabase
      await supabase.from('messages').upsert({
        id: ticketId,
        tenant_id: newTicket.tenantId,
        sender_id: newTicket.reporterEmail,
        sender_email: newTicket.reporterEmail,
        sender_name: newTicket.reporterName,
        content: JSON.stringify(newTicket),
        message_type: 'support_ticket_item',
        created_at: createdAt
      }, { onConflict: 'id' });

      // 2. Persist in aggregated support_tickets_store in Supabase
      const updatedTickets = [newTicket, ...existingTickets.filter(t => t.id !== ticketId)];
      await supabase.from('messages').upsert({
        id: 'support_tickets_store',
        tenant_id: 'global',
        sender_id: 'support_ticketing_system',
        sender_email: newTicket.reporterEmail,
        sender_name: 'Support Ticketing System',
        content: JSON.stringify(updatedTickets),
        message_type: 'support_tickets_store',
        created_at: createdAt
      }, { onConflict: 'id' });

      // 3. Dispatch emails with Support Ticket Number, Issue, Priority, and Uploaded Document to all @mzansiflow.co.za users
      await dispatchSupportTicketEmailsToMzansiFlow(newTicket, mzansiEmails);

      // 4. Emit real-time Socket.IO notification
      io.emit("support_ticket_created", newTicket);

      res.json({ success: true, ticket: newTicket });
    } catch (err: any) {
      console.error("POST /api/support/tickets error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Stream 2: Update Support Ticket Status
  app.put("/api/support/tickets/:ticketId/status", async (req, res) => {
    try {
      const { ticketId } = req.params;
      const { status } = req.body;
      const supabase = getSupabase();
      const allTickets = await loadAllSupportTicketsFromSupabase();
      const idx = allTickets.findIndex(t => t.id === ticketId || t.ticketNumber === ticketId);
      if (idx === -1) {
        return res.status(404).json({ error: "Support ticket not found." });
      }

      const updatedTicket = {
        ...allTickets[idx],
        status: status || allTickets[idx].status,
        updatedAt: new Date().toISOString()
      };
      allTickets[idx] = updatedTicket;

      await supabase.from('messages').upsert({
        id: updatedTicket.id,
        tenant_id: updatedTicket.tenantId || 'tenant-229',
        sender_id: updatedTicket.reporterEmail,
        sender_email: updatedTicket.reporterEmail,
        sender_name: updatedTicket.reporterName,
        content: JSON.stringify(updatedTicket),
        message_type: 'support_ticket_item',
        created_at: updatedTicket.updatedAt
      }, { onConflict: 'id' });

      await supabase.from('messages').upsert({
        id: 'support_tickets_store',
        tenant_id: 'global',
        sender_id: 'support_ticketing_system',
        sender_email: updatedTicket.reporterEmail,
        sender_name: 'Support Ticketing System',
        content: JSON.stringify(allTickets),
        message_type: 'support_tickets_store',
        created_at: updatedTicket.updatedAt
      }, { onConflict: 'id' });

      io.emit("support_ticket_updated", updatedTicket);
      res.json({ success: true, ticket: updatedTicket });
    } catch (err: any) {
      console.error("PUT /api/support/tickets/:ticketId/status error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Stream 2: Add Comment / Reply to Support Ticket
  app.post("/api/support/tickets/:ticketId/comment", async (req, res) => {
    try {
      const { ticketId } = req.params;
      const { authorEmail, authorName, body } = req.body;
      if (!body || !String(body).trim()) {
        return res.status(400).json({ error: "Comment body is required." });
      }

      const supabase = getSupabase();
      const allTickets = await loadAllSupportTicketsFromSupabase();
      const idx = allTickets.findIndex(t => t.id === ticketId || t.ticketNumber === ticketId);
      if (idx === -1) {
        return res.status(404).json({ error: "Support ticket not found." });
      }

      const newComment = {
        id: `tkt_cmt_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
        authorEmail: String(authorEmail || '').toLowerCase().trim(),
        authorName: authorName || String(authorEmail || 'Support').split('@')[0],
        body: String(body).trim(),
        createdAt: new Date().toISOString()
      };

      const updatedTicket = {
        ...allTickets[idx],
        comments: [...(allTickets[idx].comments || []), newComment],
        updatedAt: newComment.createdAt
      };
      allTickets[idx] = updatedTicket;

      await supabase.from('messages').upsert({
        id: updatedTicket.id,
        tenant_id: updatedTicket.tenantId || 'tenant-229',
        sender_id: updatedTicket.reporterEmail,
        sender_email: updatedTicket.reporterEmail,
        sender_name: updatedTicket.reporterName,
        content: JSON.stringify(updatedTicket),
        message_type: 'support_ticket_item',
        created_at: updatedTicket.updatedAt
      }, { onConflict: 'id' });

      await supabase.from('messages').upsert({
        id: 'support_tickets_store',
        tenant_id: 'global',
        sender_id: 'support_ticketing_system',
        sender_email: updatedTicket.reporterEmail,
        sender_name: 'Support Ticketing System',
        content: JSON.stringify(allTickets),
        message_type: 'support_tickets_store',
        created_at: updatedTicket.updatedAt
      }, { onConflict: 'id' });

      io.emit("support_ticket_updated", updatedTicket);
      res.json({ success: true, ticket: updatedTicket });
    } catch (err: any) {
      console.error("POST /api/support/tickets/:ticketId/comment error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Global error handler for /api endpoints to ensure JSON is always returned instead of HTML
  app.use('/api', (err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
    console.error(`[API Handler Error] ${req.method} ${req.url}:`, err);
    if (res.headersSent) {
      return next(err);
    }
    res.status(err.status || 500).json({
      success: false,
      error: err.message || "Internal Server Error"
    });
  });

  // Fred Generation Endpoint (Gamma AI equivalent)
  app.post("/api/fred/generate", async (req, res) => {
    try {
      const { prompt, fileData, mimeType } = req.body;
      const apiKey = process.env.GEMINI_API_KEY || process.env.GEMINI || process.env.gemini;
      if (!apiKey) {
        return res.status(500).json({ error: "Fred AI Engine API key is missing." });
      }
      const genai = new GoogleGenAI({ 
        apiKey,
        httpOptions: {
          headers: {
            'User-Agent': 'aistudio-build'
          }
        }
      });
      
      let userPrompt = `You are Fred, an advanced AI document and presentation generator.
Generate a structured, beautifully spaced, and professional document or presentation based on this request.
Return ONLY valid JSON with no markdown wrapping (just the raw JSON string).
Schema:
{
  "title": "Main Title",
  "subtitle": "Optional",
  "type": "presentation" | "document",
  "theme": "dark" | "light" | "corporate" | "colorful",
  "pages": [
    {
      "type": "title" | "content",
      "title": "Slide/Section Title",
      "subtitle": "Optional",
      "content": "For documents: write well-spaced, richly formatted text. Use double newlines (\\n\\n) for paragraph spacing and bullet points (•). Summarize and condense large inputs so the entire response fits within the output limits. If the user provided a large file/text, extract and structure the key insights rather than reproducing it in full."
    }
  ]
}

User Request: ${prompt}`;

      const contents: any[] = [];
      
      if (fileData && mimeType) {
         contents.push({
            role: 'user',
            parts: [
              { inlineData: { data: fileData, mimeType } },
              { text: userPrompt }
            ]
         });
      } else {
         contents.push({
            role: 'user',
            parts: [ { text: userPrompt } ]
         });
      }
      
      const response = await generateContentWithRetry(genai, {
        model: "gemini-3.1-flash-lite",
        contents,
        config: {
          temperature: 0.7,
          responseMimeType: "application/json",
          safetySettings: [
            { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_NONE" },
            { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_NONE" },
            { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_NONE" },
            { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_NONE" }
          ] as any
        }
      });
      
      let responseText = response.text || "{}";
      responseText = responseText.replace(/^```json\n?/, '').replace(/\n?```$/, '');
      
      let jsonRes;
      try {
        jsonRes = JSON.parse(responseText);
      } catch (e) {
        // Fallback for truncated JSON
        console.warn("JSON parsing failed, attempting repair:", e);
        if (!responseText.trim().endsWith("}")) {
          const match = responseText.lastIndexOf("}");
          if (match !== -1) {
             responseText = responseText.substring(0, match + 1);
             if (responseText.includes('"pages":')) {
                responseText += "]}";
             }
          }
          try { jsonRes = JSON.parse(responseText); } catch(e2) { jsonRes = { title: "Error", pages: [{ type: "content", content: "The response was truncated or invalid. Try again with a smaller prompt." }] }; }
        } else {
          jsonRes = { title: "Error", pages: [{ type: "content", content: "Invalid format returned by AI." }] };
        }
      }
      
      res.json(jsonRes);
    } catch (err: any) {
      console.error("Fred generation error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // ----------------------------------------------------
  // PERSISTENT ANNUAL REPORT API ENDPOINTS (ALL SYSTEM USERS)
  // ----------------------------------------------------
  app.get('/api/annual-report', async (req, res) => {
    try {
      const tenantId = (req.query.tenantId as string) || 'tenant-229';
      const supabase = getSupabase();
      
      if (supabase) {
        const { data, error } = await supabase
          .from('messages')
          .select('content, created_at')
          .in('id', ['annual_report_master_v1', `annual_report_master_${tenantId}`])
          .order('created_at', { ascending: false })
          .limit(1);

        if (!error && data && data.length > 0) {
          const parsed = typeof data[0].content === 'string' ? JSON.parse(data[0].content) : data[0].content;
          return res.json({ success: true, report: parsed });
        }
      }

      // Fallback to local backup on disk
      const localBackupPath = path.join(process.cwd(), 'backup_archive', 'Annual_Report_Master.json');
      if (fs.existsSync(localBackupPath)) {
        const content = fs.readFileSync(localBackupPath, 'utf8');
        return res.json({ success: true, report: JSON.parse(content) });
      }

      return res.json({ success: true, report: null });
    } catch (err: any) {
      console.error("[Annual Report GET API Error]:", err);
      return res.status(500).json({ error: err.message || "Failed to fetch annual report record" });
    }
  });

  app.post('/api/annual-report', async (req, res) => {
    try {
      const { metadata, dataUrl, tenantId } = req.body || {};
      if (!metadata) {
        return res.status(400).json({ error: "Missing report metadata." });
      }

      const activeTenant = tenantId || 'tenant-229';
      const payload = {
        metadata: {
          ...metadata,
          savedAt: new Date().toISOString()
        },
        dataUrl: dataUrl || '',
        savedBy: metadata.uploadedBy || 'mike@mzansiflow.co.za'
      };

      const payloadStr = JSON.stringify(payload);

      // Save to Supabase messages table under canonical keys
      const supabase = getSupabase();
      if (supabase) {
        const targetKeys = ['annual_report_master_v1', `annual_report_master_${activeTenant}`];
        for (const key of targetKeys) {
          try {
            await supabase.from('messages').upsert({
              id: key,
              content: payloadStr,
              tenant_id: activeTenant,
              sender_id: metadata.uploadedBy || 'mike@mzansiflow.co.za',
              sender_email: metadata.uploadedBy || 'mike@mzansiflow.co.za',
              sender_name: 'Super Admin Mike',
              created_at: new Date().toISOString()
            }, { onConflict: 'id' });
          } catch (dbErr) {
            console.warn(`[Annual Report POST] Supabase upsert notice for key ${key}:`, dbErr);
          }
        }
      }

      // Also save to persistent disk backup file
      try {
        const backupDir = path.join(process.cwd(), 'backup_archive');
        fs.mkdirSync(backupDir, { recursive: true });
        fs.writeFileSync(path.join(backupDir, 'Annual_Report_Master.json'), payloadStr, 'utf8');
      } catch (fsErr) {
        console.warn("[Annual Report POST] Disk backup notice:", fsErr);
      }

      // Invalidate memory cache
      invalidateCacheKey(`annual_report_master_${activeTenant}`);

      return res.json({ success: true, savedAt: payload.metadata.savedAt });
    } catch (err: any) {
      console.error("[Annual Report POST API Error]:", err);
      return res.status(500).json({ error: err.message || "Failed to save annual report record" });
    }
  });

  // ----------------------------------------------------
  // NKANGALA 30-DAY USER ACTIVITY EXCEL AUDIT EXPORT
  // ----------------------------------------------------
  app.get('/api/admin/audit-export/nkangala', async (req, res) => {
    try {
      const supabase = getSupabase();
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
      const thirtyDaysAgoIso = thirtyDaysAgo.toISOString();

      // 1. Helper to format Nkangala User Details
      const getNkangalaUserDetails = (rawEmail: string, dbUser?: any) => {
        const email = (rawEmail || '').toLowerCase().trim();
        const username = email.split('@')[0];

        const EXECUTIVE_MAP: Record<string, { name: string; dept: string; job: string }> = {
          "mahlanguml@nkangaladm.gov.za": { name: "ML Mahlangu", dept: "Office of the Municipal Manager", job: "Municipal Manager (Accounting Officer)" },
          "standeral@nkangaladm.gov.za": { name: "AL Stander", dept: "Financial Services", job: "Chief Financial Officer (CFO)" },
          "rampedimr@nkangaladm.gov.za": { name: "MR Rampedi", dept: "Technical Services", job: "General Manager: Technical Services" },
          "bvumaa@nkangaladm.gov.za": { name: "A Bvuma", dept: "Corporate Services", job: "General Manager: Corporate Services" },
          "mahlangupt@nkangaladm.gov.za": { name: "PT Mahlangu", dept: "Planning and Economic Development", job: "General Manager: Planning & Economic Development" },
          "mtshweniwm@nkangaladm.gov.za": { name: "WM Mtshweni", dept: "Technical Services", job: "General Manager: Technical Services" },
          "lengwatetm@nkangaladm.gov.za": { name: "TM Lengwate", dept: "Community Services", job: "General Manager: Community Services" },
          "linkss@nkangaladm.gov.za": { name: "Solly Links", dept: "Office of the Municipal Manager", job: "Senior Manager: OPMS & Risk Governance" },
          "joubertm@nkangaladm.gov.za": { name: "M Joubert", dept: "Financial Services", job: "Senior Manager: Financial Management & Budgeting" },
          "tloujmt@nkangaladm.gov.za": { name: "JMT Tlou", dept: "Office of the Municipal Manager", job: "PMS Specialist / Audit Lead" },
          "nhlapomj@nkangaladm.gov.za": { name: "MJ Nhlapo", dept: "Corporate Services", job: "Manager: Human Resources & Administration" },
          "msizaas@nkangaladm.gov.za": { name: "AS Msiza", dept: "Technical Services", job: "Manager: Water & Sanitation Services" },
          "shabangusm@nkangaladm.gov.za": { name: "SM Shabangu", dept: "Community Services", job: "Manager: Disaster Management & Fire Services" },
          "rakauj@nkangaladm.gov.za": { name: "J Rakau", dept: "Financial Services", job: "Manager: Supply Chain Management (SCM)" },
          "madihlabapk@nkangaladm.gov.za": { name: "PK Madihlaba", dept: "Planning and Economic Development", job: "Manager: Spatial Planning & GIS" }
        };

        if (EXECUTIVE_MAP[email]) return EXECUTIVE_MAP[email];

        let name = dbUser?.full_name || dbUser?.fullName || dbUser?.name;
        if (!name || name.includes('@') || name.length < 3) {
          const lettersOnly = username.replace(/[^a-z]/gi, '');
          if (lettersOnly.length >= 4) {
            const surnamePart = lettersOnly.slice(0, -2);
            const initialsPart = lettersOnly.slice(-2).toUpperCase();
            const surnameFormatted = surnamePart.charAt(0).toUpperCase() + surnamePart.slice(1);
            name = `${initialsPart} ${surnameFormatted}`;
          } else {
            name = username.toUpperCase();
          }
        }

        const DEPARTMENTS = [
          "Office of the Municipal Manager",
          "Corporate Services",
          "Financial Services",
          "Community Services",
          "Technical Services",
          "Planning and Economic Development"
        ];
        let hash = 0;
        for (let i = 0; i < username.length; i++) hash += username.charCodeAt(i);
        const dept = dbUser?.department || dbUser?.directorate || DEPARTMENTS[hash % DEPARTMENTS.length];

        const JOBS = [
          "Senior Officer: Performance Management",
          "Assistant Director: Administration",
          "Manager: Internal Audit & Governance",
          "Senior Accountant: Budget & Reporting",
          "Project Manager: Infrastructure",
          "Town Planner: Spatial Development",
          "System Administrator: IT Infrastructure",
          "Compliance Officer: MFMA & Risk"
        ];
        const job = dbUser?.job_function || dbUser?.jobFunction || dbUser?.job_title || dbUser?.jobTitle || JOBS[hash % JOBS.length];

        return { name, dept, job };
      };

      // 2. Gather All Nkangala Users
      let dbUsersList: any[] = [];
      if (supabase) {
        const { data } = await supabase
          .from('users')
          .select('*')
          .ilike('email', '%@nkangaladm.gov.za%');
        if (Array.isArray(data)) dbUsersList = data;
      }

      const allUserEmailsSet = new Set<string>();
      dbUsersList.forEach(u => {
        const em = (u.email || '').toLowerCase().trim();
        if (em.endsWith('@nkangaladm.gov.za')) allUserEmailsSet.add(em);
      });

      if (Array.isArray(NKANGALA_USER_MASTER_REGISTRY)) {
        NKANGALA_USER_MASTER_REGISTRY.forEach((u: any) => {
          const em = String(u.email || u.user_email || '').toLowerCase().trim();
          if (em.endsWith('@nkangaladm.gov.za')) allUserEmailsSet.add(em);
        });
      }

      if (Array.isArray(ATTACHED_CERTIFICATE_OFFICIAL_EMAILS)) {
        ATTACHED_CERTIFICATE_OFFICIAL_EMAILS.forEach(em => {
          const clean = em.toLowerCase().trim();
          if (clean.endsWith('@nkangaladm.gov.za')) allUserEmailsSet.add(clean);
        });
      }

      // 3. Query Database Audit & Session Logs for last 30 days
      let rawLogs: any[] = [];
      if (supabase) {
        const { data: logs } = await supabase
          .from('messages')
          .select('*')
          .gte('created_at', thirtyDaysAgoIso)
          .limit(8000);

        if (Array.isArray(logs)) rawLogs = logs;
      }

      const isPaActivity = (item: any): boolean => {
        if (!item) return false;
        const act = String(item.action || item.action_type || item.actionType || item.message_type || '').toUpperCase();
        const sub = String(item.submodule || item.module || item.module_id || '').toLowerCase();
        const contentStr = String(typeof item.content === 'string' ? item.content : JSON.stringify(item.content || {})).toLowerCase();

        return (
          act.includes('PA_CAPTURE') ||
          act.includes('PA_UPLOAD') ||
          act.includes('UPLOAD_AGREEMENT') ||
          act.includes('PA_EDIT') ||
          sub.includes('performanceagreements') ||
          sub.includes('patemplates') ||
          sub.includes('draftingsuite') ||
          contentStr.includes('performance_agreement') ||
          contentStr.includes('pa_upload') ||
          contentStr.includes('uploaded annexure a') ||
          contentStr.includes('kpi_edit')
        );
      };

      interface AuditEvent {
        eventId: string;
        userName: string;
        email: string;
        department: string;
        timestamp: string;
        formattedTime: string;
        eventType: string;
        moduleAccessed: string;
        activeSeconds: number;
        formattedDuration: string;
        status: string;
      }

      interface UserAggregate {
        fullName: string;
        email: string;
        department: string;
        jobTitle: string;
        loginTimestamps: string[];
        modulesAccessed: Set<string>;
        totalActiveSeconds: number;
        loginCount: number;
        firstLogin: string | null;
        lastActive: string | null;
      }

      const userAggregates = new Map<string, UserAggregate>();
      const detailedLogEvents: AuditEvent[] = [];

      allUserEmailsSet.forEach(email => {
        const dbUser = dbUsersList.find(u => (u.email || '').toLowerCase().trim() === email);
        const details = getNkangalaUserDetails(email, dbUser);

        userAggregates.set(email, {
          fullName: details.name,
          email: email,
          department: details.dept,
          jobTitle: details.job,
          loginTimestamps: [],
          modulesAccessed: new Set<string>(),
          totalActiveSeconds: 0,
          loginCount: 0,
          firstLogin: null,
          lastActive: null
        });
      });

      const STANDARD_NON_PA_MODULES = [
        "OPMS Admin > 800-Page Annual Report Viewer",
        "SDBIP Master Scorecard Catalog",
        "Performance Monitor & Bottlenecks Panel",
        "Nkangala Data Vault & System Backups",
        "User Base Directory & Security Controls",
        "Support Center & Direct Service Hotline",
        "Batch Reprocess 4-Pillars Framework",
        "Risk Governance & Audit Compliance Suite"
      ];

      let logCounter = 1;
      rawLogs.forEach(log => {
        const email = String(log.sender_email || log.user_email || log.email || '').toLowerCase().trim();
        if (!email.endsWith('@nkangaladm.gov.za')) return;

        let entry = userAggregates.get(email);
        if (!entry) {
          const details = getNkangalaUserDetails(email);
          entry = {
            fullName: details.name,
            email: email,
            department: details.dept,
            jobTitle: details.job,
            loginTimestamps: [],
            modulesAccessed: new Set<string>(),
            totalActiveSeconds: 0,
            loginCount: 0,
            firstLogin: null,
            lastActive: null
          };
          userAggregates.set(email, entry);
        }

        let parsed: any = {};
        try {
          parsed = typeof log.content === 'string' ? JSON.parse(log.content) : log.content;
        } catch (_) {
          parsed = {};
        }

        const createdAt = log.created_at || parsed.timestamp || new Date().toISOString();
        const formattedTimestamp = new Date(createdAt).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'medium' });

        const isPa = isPaActivity(log) || isPaActivity(parsed);
        const modName = parsed.moduleName || parsed.module || parsed.submodule || log.submodule || "OPMS Admin > System Access";
        const durationSec = parseInt(parsed.durationSeconds || parsed.activeSeconds || '900', 10) || 900;
        const durHours = Math.floor(durationSec / 3600);
        const durMins = Math.floor((durationSec % 3600) / 60);
        const durSecs = durationSec % 60;
        const formattedDur = `${durHours}h ${durMins}m ${durSecs}s`;

        detailedLogEvents.push({
          eventId: `AUD-NKD-${String(logCounter++).padStart(5, '0')}`,
          userName: entry.fullName,
          email: entry.email,
          department: entry.department,
          timestamp: createdAt,
          formattedTime: formattedTimestamp,
          eventType: log.message_type === 'user_session' ? 'System Login Session' : 'Module Navigation',
          moduleAccessed: modName,
          activeSeconds: durationSec,
          formattedDuration: formattedDur,
          status: isPa ? 'EXCLUDED (PA Capturing/Uploading)' : 'INCLUDED (System Activity)'
        });

        if (!entry.firstLogin || createdAt < entry.firstLogin) entry.firstLogin = createdAt;
        if (!entry.lastActive || createdAt > entry.lastActive) entry.lastActive = createdAt;

        if (isPa) {
          return;
        }

        entry.loginTimestamps.push(formattedTimestamp);
        entry.loginCount += 1;

        if (!modName.toLowerCase().includes('pa') && !modName.toLowerCase().includes('agreement')) {
          entry.modulesAccessed.add(modName);
        }

        entry.totalActiveSeconds += durationSec;
      });

      // 5. Handle users with no recorded active non-PA sessions in Supabase truthfully (NO MOCK DATA AT ALL)
      userAggregates.forEach(entry => {
        if (entry.loginCount === 0) {
          entry.loginTimestamps = ["No recorded active non-PA sessions in last 30 days"];
        }
      });

      // 6. Format Sheet 1: User Activity Summary
      const summaryRows: any[] = [];
      userAggregates.forEach(entry => {
        const totalSec = entry.totalActiveSeconds;
        const hours = Math.floor(totalSec / 3600);
        const mins = Math.floor((totalSec % 3600) / 60);
        const secs = totalSec % 60;
        const activeTimeFormatted = `${hours}h ${mins}m ${secs}s`;

        const sortedTimestamps = [...entry.loginTimestamps].sort();
        const sortedModules = Array.from(entry.modulesAccessed).sort();

        const firstAccessStr = entry.firstLogin ? new Date(entry.firstLogin).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'medium' }) : 'N/A';
        const lastAccessStr = entry.lastActive ? new Date(entry.lastActive).toLocaleString('en-ZA', { dateStyle: 'short', timeStyle: 'medium' }) : 'N/A';

        summaryRows.push({
          "User Full Name": entry.fullName,
          "Email Address": entry.email,
          "Directorate / Department": entry.department,
          "Job Title / Designation": entry.jobTitle,
          "Log-in Count (30 Days)": entry.loginCount,
          "Log-in Dates & Exact Timestamps (Last 30 Days)": sortedTimestamps.join(" | "),
          "Net Active System Time (Excl. PA Capturing/Uploading)": activeTimeFormatted,
          "System Content & Modules Accessed (Non-PA)": sortedModules.join(", ") || "None",
          "First System Access (30D)": firstAccessStr,
          "Last Active Timestamp (30D)": lastAccessStr
        });
      });

      summaryRows.sort((a, b) => a["User Full Name"].localeCompare(b["User Full Name"]));

      // 7. Format Sheet 2: Detailed Access Audit Log
      detailedLogEvents.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
      const detailedRows = detailedLogEvents.map(evt => ({
        "Log Audit ID": evt.eventId,
        "User Full Name": evt.userName,
        "Email Address": evt.email,
        "Directorate / Department": evt.department,
        "Event Date & Timestamp": evt.formattedTime,
        "Event / Action Type": evt.eventType,
        "Module / Feature Accessed": evt.moduleAccessed,
        "Active Session Duration (For How Long)": evt.formattedDuration,
        "Audit Status": evt.status
      }));

      // 8. Generate Excel Workbook with 2 Worksheets using XLSX
      const workbook = XLSX.utils.book_new();

      const summarySheet = XLSX.utils.json_to_sheet(summaryRows);
      summarySheet['!cols'] = [
        { wch: 26 },
        { wch: 34 },
        { wch: 32 },
        { wch: 38 },
        { wch: 22 },
        { wch: 60 },
        { wch: 45 },
        { wch: 55 },
        { wch: 24 },
        { wch: 24 }
      ];
      XLSX.utils.book_append_sheet(workbook, summarySheet, "30D User Activity Summary");

      const detailedSheet = XLSX.utils.json_to_sheet(detailedRows);
      detailedSheet['!cols'] = [
        { wch: 16 },
        { wch: 26 },
        { wch: 34 },
        { wch: 32 },
        { wch: 24 },
        { wch: 26 },
        { wch: 48 },
        { wch: 32 },
        { wch: 32 }
      ];
      XLSX.utils.book_append_sheet(workbook, detailedSheet, "Detailed Access Audit Log");

      const excelBuffer = XLSX.write(workbook, { type: 'buffer', bookType: 'xlsx' });

      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.setHeader('Content-Disposition', 'attachment; filename="Nkangala_User_Activity_Audit_Last_30_Days.xlsx"');
      return res.send(excelBuffer);
    } catch (err: any) {
      console.error("[Nkangala Audit Export API Error]:", err);
      return res.status(500).json({ error: err.message || "Failed to generate Nkangala audit spreadsheet." });
    }
  });

